programs.sol:
"""Approximate a horizontal-layout-whitespace response.

Tabs after printed line numbers and spaces after textual line prefixes
(escaped newlines, diff markers, comments, listing gutters) are negative.
Ordinary indentation after a real newline is nearly silent; mixed tabs and
spaces are not. Run length changes the response size. Nonbreaking spaces
in backtick-marked code and initial-position whitespace have separate rules.
Most other tokens receive zero. State is reset at document boundaries.
"""
import math
import re

READS = ()


def whitespace_value(s, previous, line, first):
    numbered = re.fullmatch(r' *[0-9]+', line) is not None
    newline = previous.endswith(('\n', '\r'))
    indentation = not line.strip()
    n = len(s)

    if s and not s.strip(' '):
        if first:
            return 4.0 if n == 3 else -0.3
        if newline:
            return 0.03
        if indentation:
            return -0.5 if '\t' in previous else -0.05
        if re.search(r'\\+n$', line):
            return -min(4.15, 1.9 + 1.2 * math.log(n))
        if line.strip() in ('+', '-', '|', '│', '>'):
            return -min(3.2, 1.75 + 0.55 * math.log(n)) if n >= 3 else -0.3
        if numbered and line.startswith(' ') and n >= 4:
            return -4.5
        if re.fullmatch(r' */\* *[0-9]+ *\*/', line):
            return -4.5 if n >= 3 else -1.8
        if re.search(r'(?:^ *[0-9]+ *[|│:]|:[0-9]+:)$', line):
            return -min(4.5, 1.5 + 1.25 * math.log(n))
        if previous.isspace() and n >= 3 and '\t' in line:
            return -min(4.7, 3.0 + 0.4 * math.log(n))
        if previous.rstrip().endswith('#') and n >= 3:
            return -3.5
        if previous.rstrip().endswith(('//', '/*', '--')):
            return -min(3.2, 1.5 + 0.5 * math.log(n))
        if previous.endswith(('"', "'")):
            return -2.2 if n >= 3 else -0.25
        return 0.0 if n == 1 else -0.1

    if s == r'\t':
        return 3.5 if first else -1.3

    if s and not s.strip('\t'):
        if first:
            return 6.3 if n == 1 else 0.6
        if numbered:
            return -3.4 if n == 1 or not line.startswith(' ') else -5.7
        if newline:
            return 0.08
        if indentation:
            return -4.0 if ' ' in line and '\t' in line else -1.0
        return -2.0 if previous.isspace() else -0.4

    if '\t' in s and not s.strip('\t '):
        spaces, tabs = s.count(' '), s.count('\t')
        if numbered:
            return -min(7.4, 4.77 + 0.78 * math.log(max(1, spaces)))
        if newline or indentation:
            if s.startswith(' '):
                return -1.5
            return -min(3.0, 0.4 * spaces / tabs)
        return -0.6

    if s.startswith('\t'):
        if '\n' in s or '\r' in s:
            return -0.7 if numbered else -0.15
        if numbered:
            return -2.1
        if newline:
            return 0.1
        if indentation:
            return -3.5 if ' ' in line and '\t' in line else -0.15
        return -0.5

    if '\xa0' in s and not s.strip(' \xa0'):
        if ' ' in s:
            return 0.15
        if '`' in line:
            return -3.2 if n > 1 or previous.isspace() else -0.3
        return -0.3 if previous.isspace() or n > 1 else -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, line = '', ''
    else:
        _, previous, line = carry
    s = prefix.token_strings[-1]
    value = whitespace_value(s, previous, line, first)
    line = (line + s).replace('\r', '\n').rsplit('\n', 1)[-1][-256:]
    return (doc, s, line), value

"""Approximate a document-opening response from familiar written forms.

The large training responses mostly occur at a document's first token or an
initial run of identical tokens. Estimates use script, case, punctuation,
subject pronouns, question words, and two code keywords. An opening run of 1s
followed by 2s gets a separate fading pulse. Elsewhere predict nearly zero.
Most word-specific and contextual variation is deliberately left unexplained.
"""
import regex
from functools import lru_cache

READS = ()

@lru_cache(maxsize=8192)
def opening(text):
    s = text.strip()
    if regex.search(r'\p{Script=Cyrillic}', s):
        return 2.34 if len(text) == 1 else 1.62
    if regex.search(r'\p{Script=Arabic}', s):
        return 1.92
    if text == 'import':
        return 2.22
    if text == 'theorem':
        return -2.44
    # First/third-person subjects, then common question openers.
    if s in {'I', 'We', 'He', 'She', 'It', 'They'}:
        return -0.70
    if s in {'How', 'Why', 'When', 'Where', 'Who', 'What'}:
        return -1.0
    if s and set(s) == {'·'} and len(s) >= 2:
        return 4.07
    if s and set(s) == {'^'} and len(s) >= 4:
        return 6.14
    if '/' in text:
        if s == '/' and '\n' in text:
            return 8.21
        if s == '/':
            return 3.25
        return 2.4 if '*' in s else 0.45
    if '\\' in text:
        return -2.8 if '(' in s or '{' in s else -1.8
    if '\n' in text:
        if not s:
            if text.startswith(' '):
                return -0.13
            return 0.36 if len(text) == 1 else -2.75
        if '\n\n' in text:
            return 0.66
        if s in {'|', '||'}:
            return 6.44
        if s == '-':
            return 5.59
        if s == '.':
            return 3.83
        return 1.74 if len(text) <= 2 else 0.66
    if len(s) == 1 and s.isalpha():
        if regex.search(r'\p{Script=Hangul}', s):
            return 1.79
        if regex.search(r'\p{Script=Katakana}', s):
            return 1.52
        return -0.59 if s.isascii() else -0.16
    if s.isupper():
        return 0.71
    if ')' in text:
        return -2.61 if '.' in text else -0.65
    if s.startswith('#'):
        return -0.71 if len(s) <= 3 else 0.94
    return -0.064


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    # Reset both the repeated-token run and the decimal-prefix counters.
    if carry is None or carry[0] != doc:
        first, same, ones, twos = text, True, int(text == '1'), 0
    else:
        _, first, same, ones, twos = carry
        same = same and text == first
        if ones and text == '1' and not twos:
            ones += 1
        elif ones and text == '2':
            twos += 1
        else:
            ones = twos = 0
    if same:
        value = opening(text)
    elif twos:
        value = 7.24 * ones ** -0.18 * 0.391 ** (twos - 1)
    else:
        value = -0.001
    return (doc, first, same, ones, twos), float(value)

programs.haiku:
"""Document-start lexicon: what layers.1.mlp.down_proj:2433 does at a document's first token.

This component is nearly silent. Its activation is large only at the first token of a
document: the token right after <|endoftext|>, or the first token of a packed row. There
the model has no earlier context, so the activation is set by that one token's kind.
This program predicts it from the kind of token, and predicts 0 everywhere else.

Raised (positive):
  Cyrillic letters (most), then Arabic, Thai, Hangul and kana letters
  a token ending in punctuation and then one line break, e.g. ".\\n", "/\\n", "},\\n"
  a code keyword or directive: import, const, #include, #ifndef, /**, CREATE
  a word written in capitals, e.g. BACKGROUND

Lowered (negative):
  a backslash escape, e.g. "+\\", "(\\", "{\\"  (the most negative)
  blank lines: "\\n\\n" or more
  a closing bracket or ")." after code
  a token containing "#"
  a single letter (A, b, S), or a lowercase word, slightly

Weights were set by fitting these kinds to how often each token starts a document.
"""

READS = ()

KEYWORDS = {
    "import", "const", "#include", "#ifndef", "#pragma", "#define", "/**", "/*", "#!/", "CREATE",
}
CYRILLIC = (0x0400, 0x04FF)
OTHER_SCRIPTS = [(0x0600, 0x06FF), (0x0E00, 0x0E7F), (0xAC00, 0xD7AF), (0x3040, 0x30FF)]


def _has_char_in(s, ranges):
    return any(lo <= ord(ch) <= hi for ch in s for lo, hi in ranges)


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not doc_start:
        return None, 0.0
    core = s.strip()
    v = 0.0
    if _has_char_in(s, [CYRILLIC]):
        v += 2.2
    elif _has_char_in(s, OTHER_SCRIPTS):
        v += 1.3
    if "\n" in s and core and not core[-1].isalnum():
        v += 1.5
    if core == "" and s.count("\n") >= 2:
        v -= 2.0
    if "\\" in s:
        v -= 1.8
    elif core and any(c in s for c in ")]}") and "\n" not in s:
        v -= 0.7
    if core in KEYWORDS:
        v += 1.0
    if len(core) >= 2 and core.isalpha() and core.isupper():
        v += 0.9
    if len(core) == 1 and core.isalpha():
        v -= 0.4
    elif len(core) > 1 and core.isalpha() and core.islower():
        v -= 0.2
    if "#" in s:
        v -= 0.5
    return None, v

programs.sol:
"""Approximate pulses from mapping punctuation and filesystem syntax.

Quoted key colons are boosted on the first key; bare colons need local
identifier/object syntax, with damping for declarations, CSS and LaTeX.
Other rules recognize quoted-key arrows, Unix directories, Windows drives,
and the final digit of c2/e2 byte escapes. Chat/include markers and whitespace
get simple document-start offsets. Word-specific start effects are omitted.
Only the last 160 characters are carried, resetting between documents.
"""
import re

READS = ()
PATH_HEADS = {
    'workspace': 2.0, 'usr': 1.8, 'opt': 2.3,
    'tmp': 1.3, 'home': 2.8, 'root': 1.2, 'etc': 1.1,
}
FIRST_KEY = re.compile(r'\{\s*[\'\"]?[^\s{}:,\'\"]+$')


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    tail = '' if fresh else carry[1]
    value = 0.0
    if fresh:
        if token == '<|im_start|>':
            value = 1.7
        elif token.startswith('#include'):
            value = 2.55
        elif token.isspace():
            value = 0.7 if '\n' in token else 1.5
            if token == ' ':
                value = 0.45
            elif '\r' in token:
                value = 2.6
        else:
            value = 0.05
    elif token in ('":', "':", '\\":'):
        value = 2.25 if FIRST_KEY.search(tail) else 1.5
        if token == "':":
            value -= 0.2
    elif token in ('":"', ':"', ":'"):
        value = 0.6
    elif token == ':':
        key = re.search(r'(?:^|[{,]|\s{2})\s*[A-Za-z_$][\w$]*$', tail)
        if key:
            opening = tail.rfind('{')
            value = 0.2
            if opening > tail.rfind('}'):
                before = tail[:opening].rstrip()
                declaration = re.search(
                    r'\b(?:class|interface|struct|enum|type)\s+[^{};=()\n]*$',
                    before)
                latex = re.search(r'\\[A-Za-z]+$', before)
                css = re.search(r'(?:^|[\n}])\s*[.#][\w.# :>\-]+$', before)
                if not (declaration or latex or css):
                    value = 1.65
    elif token in PATH_HEADS and tail.endswith('/'):
        value = PATH_HEADS[token]
    elif token == '/workspace':
        value = 0.62
    elif token == '/local' and tail.endswith('usr'):
        value = 2.35
    elif token == '/lib':
        value = 1.3 if tail.endswith(('usr', '/local')) else 0.3
    elif token == ':\\' and re.search(r'\b[A-Z]$', tail):
        value = 2.5
    elif token == '2' and re.search(r'\\x[ce]$', tail, re.I):
        value = 0.8 if tail.endswith('e') else 0.52
    elif token == ' =>' and re.search(r'[\'\"][\w-]+[\'\"]$', tail):
        value = 1.55
    return (doc, (tail + token)[-160:]), value

programs.haiku:
"""Object-literal key colons, path-root words, and key-arrows in data literals.

Fires on a few kinds of token that all sit inside structured data (JSON, JS/TS object
literals, PHP arrays) or on a few Unix system-directory names:
  * the colon after a key inside an open `{`, strongest on the first key right after
    the brace (`{ name:`, `{path:`), weaker on later keys;
  * a closing quote + colon `":` (a JSON key), strongest; `':` and `:"` are weaker;
  * a PHP-style `'key' =>` arrow, and `<|im_start|>` right after `<|endoftext|>`;
  * the path-root words `workspace`, `opt`, `usr`, `tmp`, `root`, `etc`, `/local`.
Everything else predicts 0; a colon outside braces is near 0 (type annotations, prose).
"""

READS = ()

KEY_END = {'":', '\\":'}          # closing quote + colon: a JSON or dict key
QUOTE_COLON = {"':", ':"'}           # other quote-colon pairs, weaker
PATH_ROOT = {'workspace': 2.0, '/workspace': 0.7, '/local': 2.5, 'opt': 2.0, 'usr': 1.6,
             'tmp': 1.3, 'root': 1.0, 'etc': 1.0}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ''
    if carry is None or prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        depth, since = 0, 99          # open braces, and meaningful tokens since the last '{'
    else:
        depth, since = carry
    if s in KEY_END:
        v = 1.7
    elif s in QUOTE_COLON:
        v = 0.9
    elif s in PATH_ROOT:
        v = PATH_ROOT[s]
    elif s == ':':
        v = (1.8 if since == 1 else 0.9) if depth > 0 else 0.1
    elif s == ' =>' and prev[-1:] in ("'", '"'):
        v = 1.0
    elif s == '<|im_start|>' and prev == '<|endoftext|>':
        v = 1.7
    else:
        v = 0.0
    if '{' in s:
        since = 0
    elif s.strip(" \"'\n\t"):
        since += 1
    depth = max(0, depth + s.count('{') - s.count('}'))
    return (depth, since), v

programs.sol:
"""Document-opening syntax, with a particularly strong 'Title:' response.

A colon immediately following document-initial 'Title' gets a large activation.
At the first token, headings and ordinary cased text get smaller offsets based
on their typography. Elsewhere this is a background approximation; it does not
attempt to reproduce the component's scattered rare-subword responses.
"""
READS = ()


def opening_value(token):
    text = token.strip()
    if token.startswith('#'):
        return 0.48
    if token.startswith('<|'):
        return -0.11
    if token.startswith('\\'):
        return 0.39
    if text in {'"', "'", '"""', "'''", '`'}:
        return 0.29
    if text.isdigit():
        return 0.10
    if text.isascii() and text.isalpha():
        if text.istitle():
            return 0.10 if token.startswith(' ') else 0.17
        if text.islower():
            return 0.02 if token.startswith(' ') else 0.09
        return 0.0
    if text.isalpha():
        return 0.02
    return 0.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    token = prefix.token_strings[-1]
    value = opening_value(token) if position == 0 else 0.003
    if position == 0 and token == 'Title':
        value = 0.516
    elif position == 1 and previous == 'Title' and token == ':':
        value = 10.1053
    return (doc, position + 1, token), value

"""Partial lexical-collocation detector: positive for selected person endings,
sports institutions, and civic/professional compounds; negative for selected
sporting events, travel compounds, and work intervals. Only the newly supplied
ending or phrase-head token receives a response. Everything else receives zero.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    match = re.search(r'([a-z]+)$', tail.lower())
    stem = match.group(1) if match else ''
    head = token.strip().lower()
    value = 0.0

    # Derivational endings that turn a word into a person designation.
    if token[:1].isalpha() and head in {'er', 'ers', 'ee', 'ees'}:
        if stem == 'football' and head in {'er', 'ers'}:
            value = 4.25 if head == 'er' else 2.9
        elif stem == 'car' and head in {'er', 'ers'}:
            value = 6.7
        elif stem in {'falcon', 'campaign', 'ball', 'tour'} and head in {
            'er', 'ers'
        }:
            value = 2.3 if head == 'er' else 1.0
        elif stem == 'train' and head in {'ee', 'ees'}:
            value = 1.4

    # Clubs and sporting institutions versus games and series.
    elif stem == 'football':
        if head in {'league', 'club', 'association', 'federation'}:
            value = 1.4
        elif head in {'game', 'games', 'season'}:
            value = -1.5
    elif stem == 'rugby' and head in {'league', 'union'}:
        value = 1.5
    elif stem in {'cricket', 'soccer', 'book'} and head == 'club':
        value = 1.1
    elif stem == 'fa' and head == 'cup':
        value = 2.4
    elif stem == 'world' and head == 'series':
        value = -3.2
    elif stem == 'country' and head in {'club', 'music'}:
        value = -1.9

    # Civic documents, labour organizations, and healthcare occupations.
    elif stem == 'ballot' and head in {'paper', 'papers'}:
        value = 5.3 if head == 'paper' else 4.4
    elif stem in {'trade', 'trades'} and head in {'union', 'unions', 'un'}:
        value = 3.8
    elif stem == 'trade' and head == 'mark':
        value = 4.0
    elif stem in {'healthcare', 'care', 'sports', 'health'} and head in {
        'professional', 'professionals'
    }:
        value = 0.9 if stem == 'health' else 3.0

    # A few conventional travel and work expressions have the opposite sign.
    elif stem == 'road' and head in {'course', 'courses', 'trip', 'trips'}:
        value = -3.0 if head in {'course', 'courses'} else -1.9
    elif stem == 'work' and head in {'day', 'days', 'periods', 'ethic', 'week'}:
        value = -2.5
    elif stem in {'holiday', 'flu'} and head in {'season', '-season'}:
        value = -2.6
    elif stem == 'phone' and head in {'call', 'calls'}:
        value = -1.5

    return (doc, (tail + token)[-64:]), value

"""A sparse lexical approximation of declaration and formatting syntax.

Observed large responses cluster around source declarations and markup.
The rules below assign positive values to line-start access modifiers,
integer/void declarations and author fields, and negative values to type
annotations, accessor syntax, bullets and separators. Indentation and blank
lines modify these values. Unrecognized tokens get zero.

This is not a complete parser: it keeps only 400 preceding characters,
treats escaped newlines as line breaks, and resets at document boundaries.
Rarer language-specific effects from the larger trial are deliberately omitted.
"""
import re

READS = ()

# Access modifiers: line, after blank line, tab.
ACCESS = {
    'public': (1.31, 0.27, 0.17),
    'private': (0.62, 0.35, 0.02),
    'protected': (0.73, 0.1, 0.27),
}

# Primitive types: line, blank line, tab, modifiers, private, static, elsewhere.
TYPES = {
    'integer': (0.55, 0.33, 0.03, 0.79, 0.42, 0.2, -0.03),
    'void': (0.35, 0.27, 0.13, 0.33, 1.16, 0.12, 0.04),
}
TYPE_FAMILY = {}
for family, words in {
    'integer': 'int long short byte unsigned signed',
    'void': 'void',
}.items():
    TYPE_FAMILY.update(dict.fromkeys(words.split(), family))
MODIFIERS = set(ACCESS) | {
    'static', 'final', 'const', 'abstract', 'virtual', 'inline', 'extern',
    'volatile', 'unsigned', 'signed',
}

# Other declaration headers: line, after blank line, after modifiers.
LINE_WORDS = {
    'def': (-0.03, 0.38, 0.0),
    'func': (0.5, 0.24, 0.18),
    'static': (0.48, -0.04, 0.53),
}

# Property accessors: after private, at an accessor boundary, after modifiers.
ACCESSORS = {
    'get': (-2.48, -0.79, 0.07),
    'set': (-3.81, -0.88, -1.42),
}
BULLETS = {'*': -0.34, '•': 0.01}
KEYWORDS = set(ACCESS) | set(TYPE_FAMILY) | set(LINE_WORDS) | {
    'class', 'interface', 'enum', 'struct', 'type', 'author', 'Override',
    'async', 'get', 'set',
}
MARKERS = {'-', '*', '•', '>', ':', '.', '..', '#', '<', '+++',
           '\u200b'}

def activation(token, past):
    s = token.strip()
    repeated = len(s) > 1 and set(s) == {'-'}
    if s not in KEYWORDS and s not in MARKERS and not repeated:
        return 0.0
    h = past.replace('\\n', '\n').replace('\\t', '\t')
    line = h.rsplit('\n', 1)[-1]
    code = re.sub(r'^\s*\d+\t', '', line).strip()
    start = not code
    blank = bool(re.search(r'\n[ \t\r]*\n[ \t\r\d]*$', h))
    leading, tab = token[:1].isspace(), token.startswith('\t')
    words = code.split()
    modifiers = bool(words) and all(w in MODIFIERS for w in words)

    if s in ACCESS:
        base, fresh, tabs = ACCESS[s]
        if start or code in {'//', '//public'}:
            return base + fresh*blank + tabs*tab
        return 0.0
    if s in TYPE_FAMILY:
        base, fresh, tabs, modified, private, static, other = TYPES[TYPE_FAMILY[s]]
        if start:
            return base + fresh*blank + tabs*tab
        if modifiers:
            return (modified + private*('private' in words)
                    + static*('static' in words))
        return other
    if s in {'class', 'interface', 'enum', 'struct'}:
        if modifiers:
            return -1.79 if 'static' in words else -0.32
        return -0.05 if start else -0.06
    if s in LINE_WORDS:
        base, fresh, modified = LINE_WORDS[s]
        return base + fresh*blank if start else modified if modifiers else 0.0
    if s == 'type':
        if code.endswith('@'): return -2.61
        if start: return -1.01
        if re.search(r'\b(export|declare|import)\s*$', code): return -1.28
        return -0.65 if code.endswith(('"', "'", '{', ',')) else -0.02
    if s == 'author':
        if code.endswith('@'): return 3.18
        return 2.32 if start else 0.0
    if s == 'Override': return -0.48
    if s == 'async': return -1.43 if start else -0.4
    if s in {'get', 'set'}:
        private, accessor, method = ACCESSORS[s]
        if code.endswith('private'): return private
        if start or code.endswith(('{', ';')): return accessor
        if modifiers: return method
        return -0.74 if h.endswith('._') else 0.0
    if s == '-':
        if not start: return 0.0
        intro = bool(re.search(r':\s*$', h))
        return (-0.2 - 0.45*leading
                - 0.1*(len(line) >= 2)
                - 0.17*blank - 0.49*intro)
    if s in {'*', '•'}:
        if not start: return 0.0
        comment = (h.rfind('/*') > h.rfind('*/') or
                   bool(re.search(r'\n\s*\*[^\n]*\n\s*$', h)))
        return (BULLETS[s] - 0.24*blank + 0.24*comment)
    if s == '>':
        return -0.8 if start else 0.0
    if s == ':':
        if start: return 0.14 - 0.72*bool(leading or line)
        if code.lower() in {'author', '- author'}: return 1.48
        if code == 'Title':
            return -2.76 if past.strip() == 'Title' else -0.03
        return 0.0
    if s == '.':
        return (-0.05 - 0.32*(code == '1')
                if re.fullmatch(r'\d{1,3}', code) else 0.0)
    if s == '..': return -1.19 if start else 0.0
    if s == '#':
        if code.endswith('{'): return -0.9
        return -1.88 if code.endswith('///') else 0.0
    if s == '<': return -1.57 if code.endswith('///') else 0.0
    if s == '+++': return -1.84 if start else 0.0
    if s == '\u200b': return -1.34
    if set(s) == {'-'}:
        tests = bool(re.search(r'(=== RUN|--- (PASS|FAIL|SKIP):)', h))
        diff = bool(re.search(r'(diff --git|index [a-f0-9]+\.\.)', h))
        table = bool(code and not code.strip('| :'))
        return ((-0.28 if start else 0.01)
                - 0.26*(len(s) == 3) - 0.17*(len(s) > 3)
                - 0.06*leading - 0.56*tests
                - 0.77*diff - 1.03*table)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    past = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = activation(token, past)
    return (doc, (past + token)[-400:]), float(value)

"""Surface-format approximation: posting ages, title labels, and code markup.

Relative-past 'ago' is strongest in posting-age labels and weaker in prose,
especially after years. Opening 'Title:' and several structured-text
conventions have separate responses. A negative prior at each document's
first token captures a broad start-of-document effect; otherwise the prior
is near zero. This intentionally leaves most small lexical variation out.
"""
import re

READS = ()

# Time unit: prose, parenthesized posting age, isolated posting age.
AGES = {
    'year': (0.02, 1.4, 1.4),
    'month': (0.9, 4.2, 5.8),
    'week': (0.6, 3.0, 4.0),
    'day': (1.8, 4.0, 5.0),
    'hour': (2.8, 5.8, 5.8),
    'minute': (2.0, 4.0, 5.0),
    'second': (2.0, 4.0, 5.0),
}


def predict(token, before, position):
    word = token.strip()
    if word == ':' and position == 1 and before == 'Title':
        return 5.35
    if word == 'ago':
        units = (r'(years?|months?|weeks?|days?|hours?|minutes?|seconds?)'
                 r'\s*$')
        unit = re.search(units, before, re.I)
        if unit:
            name = unit[1].lower().rstrip('s')
            stem = before[:unit.start()]
            isolated = re.search(r'(?:^|\n| - )\s*(\d+)\s*$', stem)
            parenthetic = re.search(r'\(\s*\d+\s*$', stem)
            posted = re.search(r'\bPosted\s+(\d+)\s*$', stem, re.I)
            style = 2 if isolated else 1 if parenthetic or posted else 0
            value = AGES[name][style]
            if name == 'year' and style:
                number = re.search(r'(\d+)\s*$', stem)
                if number:
                    value /= 1 + max(int(number[1]) - 4, 0) / 2
            return value
        if re.search(r'(?:\d+y|\(s\)|jaar|giorni|año)\s*$', before):
            return 2.5
        return 0.05
    if word == 'UTC' and re.search(r'\d:\d\d(?::\d\d)?\s*(?:[ap]m)?\s*$',
                                   before, re.I):
        return 0.7 if re.search(r'[ap]m\s*$', before, re.I) else 1.8
    if word == '前':
        if before.endswith('年'):
            return 0.5 if before.endswith('一年') else 0.02
        if before.endswith('月'):
            return 0.6
        if before.endswith(('周', '点')):
            return 1.3
    if word == 'Post' and re.search(r'\bLast\s*$', before):
        return 1.4
    if word == 'reply' and re.search(r'\bLatest\s*$', before):
        return 1.1
    if word == 'permalink':
        return 0.6 if token[:1].isspace() else -0.27
    if word == 'array':
        if re.search(r'\\begin\{$', before):
            left = re.search(r'\\left\s*([\[(|])[\s{]*\\begin\{$', before)
            return (2.95 if left[1] == '[' else 1.7) if left else 0.6
        if re.search(r'\\end\{$', before):
            return 0.14
    if word == 'lombok' and re.search(r'\bimport\s*$', before):
        return -0.9
    if word == '@Override':
        return 0.7
    if word == '@' and re.search(r'/\*\*\s*$', before):
        return -1.1
    if word == 'protected' and before.endswith('[email'):
        return 2.3
    if word == '/python' and '/bin' in before[-12:]:
        shebang = before.rsplit('\n', 1)[-1].startswith('#!')
        return -3.4 if shebang else -0.17
    if word and set(word) == {'·'} and len(word) >= 2:
        return -0.57
    return -0.26 if position == 0 else -0.0005


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        before, position = '', 0
    else:
        _, before, position = carry
    token = prefix.token_strings[-1]
    value = predict(token, before, position)
    return (document, (before + token)[-200:], position + 1), value

"""A small-number / indentation contrast in the early MLP.

Predict positive values for zero padding, decimal zeros, zeros in labels,
and ones completing small numbers. Short even-length space-only tokens
after a newline are negative, more strongly when that newline is attached
to text. Wider runs respond less; most ordinary text stays near zero.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, digits, lead = '', '', ''
    else:
        _, prev, digits, lead = carry
    s = prefix.token_strings[-1]
    value = 0.0
    if s == '0':
        value = -0.04
        if digits and set(digits) == {'0'}:
            value = 0.8
            if lead == ',':
                value = 0.06  # Thousands separators, not zero padding.
            elif len(digits) >= 3:
                value = 1.4
            elif lead == '.':
                value = 0.65
            elif lead == '[':
                value = 1.1
        elif len(digits) - len(digits.rstrip('0')) >= 3:
            # Long zero suffixes of round integers, e.g. 10000.
            zeros = len(digits) - len(digits.rstrip('0'))
            value = 0.52 if zeros == 3 else 0.84
        elif digits == '3':
            value = 0.46
        elif prev.endswith('.'):
            value = 0.16
        elif prev and prev[-1].isalpha():
            value = 0.6
        elif prev and prev[-1] in '_^':
            value = 0.3
        elif prev.endswith('-'):
            value = 0.13
    elif s == '1':
        if digits in ('1', '2', '3'):
            value = 0.54 if digits == '1' else 0.45
        elif len(digits) == 1 and digits > '3':
            value = 0.13 if digits == '4' else 0.03
        elif digits in ('01', '02'):
            value = 0.36
        elif digits == '0':
            value = -0.3 if lead in ('-', '/') else -0.06
        elif not prev:
            value = 0.205
        elif prev.endswith('\n'):
            value = 0.12
    elif s and s.strip(' ') == '':
        n = len(s)
        if n == 1:
            value = -0.16 if prev.endswith('\n') else -0.015
        elif n % 2 == 0:
            if prev.endswith('\n'):
                strength = 0.74 if not prev.strip() else 1.05
                if prev.rstrip().endswith('{'):
                    strength += 0.2
                value = -strength * math.exp(-max(n - 4, 0) / 5)
            else:
                value = -0.07 if n == 2 else 0.0
        elif n <= 15:
            value = 0.12 if n % 4 == 1 else 0.02
    elif s and s.strip('\t ') == '':
        spaces = len(s) - len(s.rstrip(' '))
        value = -0.75 if spaces >= 4 else -0.5 if spaces == 2 else 0.04
    elif s and s.strip('\u00a0') == '':
        value = -0.25 if len(s) % 2 == 0 else 0.1 * math.log2(len(s) + 1)
    elif s in '23456789' and len(s) == 1:
        value = -0.02
    if s and s.isascii() and s.isdigit():
        if not digits:
            lead = prev[-1:]
        digits = (digits + s)[-12:]
    else:
        digits = ''
    return (doc, s, digits, lead), value

"""A context-onset pulse, sized by familiar token classes.

At row starts and packed-document boundaries, selected code openings get
large values; prose, punctuation, scripts and digits get smaller class averages.
An initial run of identical tokens keeps the pulse. Everything after that is
zero: lexical idiosyncrasies and small later contextual fluctuations are omitted.
"""
import math
import regex

READS = ()
PREPOSITIONS = set('''of to in for on with at by from as into through over under
    about after before between without within against during upon'''.split())
CONJUNCTIONS = set('and or but nor yet so'.split())
PRONOUNS = set('''i we you he she it they me us him her them my our your his
    their its myself yourself themselves'''.split())


def opening(s):
    t = s.strip()
    w = t.lower()
    spaced = s.startswith(' ')
    if t == '#include':
        return 31.9
    if s == '<|endoftext|>':
        return 12.1
    if s.startswith('<|'):
        return 3.2
    if not t:
        if s == '\t':
            return 16.7
        if s == '\r':
            return -2.9
        if '\t' in s:
            return 6.5
        if '\n' in s:
            return 3.8
        return 3.1 + 1.6 * math.log(max(1, len(s)))
    if t.isdecimal():
        return 0.4
    if not spaced and t in {'import', 'def', 'class', 'function'}:
        return 12.1
    if t == 'print':
        return 13.0 if spaced else 24.8
    if w in {'question', 'answer', 'title'}:
        return 10.9
    if w == 'the':
        if t[0].isupper():
            return 6.7
        return 3.3 if spaced else 11.3
    if w in {'a', 'an'}:
        return 4.2
    if w in PREPOSITIONS:
        return 0.9 if spaced else 2.7
    if w in CONJUNCTIONS:
        return 1.8
    if w in PRONOUNS:
        return 3.6
    if regex.search(r'\p{Han}|\p{Cyrillic}|\p{Hiragana}|\p{Katakana}', t):
        return 1.5
    if regex.search(r'\p{Arabic}', t):
        return 2.6
    if regex.search('[A-Za-z]', t):
        if not t[0].isalpha():
            return 5.5
        return 4.0 if len(t) == 1 and not spaced else 3.2
    if t == '//':
        return -11.4 if '\n' in s else 2.9
    if t.startswith('/*'):
        return 6.0
    if '\\' in t or t.startswith('__'):
        return 7.5
    if not spaced and t.startswith('{'):
        return 14.0
    if '<' in t:
        return 7.3
    if '#' in t:
        return 5.1
    if '\n' in s:
        return 3.5
    if all(c in '.,;:!?' for c in t):
        return 1.1
    return 1.9


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = opening(prefix.token_strings[-1])
        return (doc, token, value, True), value
    old_doc, initial_token, value, initial_run = carry
    initial_run = initial_run and token == initial_token
    return (doc, initial_token, value, initial_run), value if initial_run else 0.0

"""Opening quotes at structured-data boundaries, especially mapping keys.

A quote after a comma gets a strong negative value when the preceding item
was a mapping value (a colon followed by a string or an unquoted expression).
Long strings and indentation weaken this response. List strings, object
openers, and opening bold markers have smaller responses. Other tokens
are approximated by zero, except for initial indentation. Syntax uses a short
document-local buffer, reset at every new row or document.
"""
import re

READS = ()
# A mapping separator, then an unquoted value, then its terminating comma.
MAPPING_VALUE = re.compile(
    r'(?:[:]|=>)[ \t]*'
    r'(?:[+-]?[\w.$]+(?:[ \t]*[-+*/][ \t]*[+-]?[\w.$]+)*|<[\w-]+>),\s*$'
)


def previous_string(text, quote):
    """Split around the last two unescaped quote marks."""
    pieces = re.split(r'(?<!\\)' + re.escape(quote), text)
    if len(pieces) < 3:
        return '', '', text
    return pieces[-3].rstrip(), pieces[-2], pieces[-1].strip()


def predict(s, previous, history):
    # At the start of a context, distinguish a lone separator from an indent.
    if not history and s and not s.strip(' \t'):
        if s == ' ':
            return 0.17
        return -0.5 if '\t' in s or len(s) == 2 else -1.0
    if s.strip() in ('**', '***'):
        opening = previous.rstrip().endswith(('.', '-'))
        return -0.35 if opening or previous.endswith('\n\n') else 0.0
    if not s.endswith(('"', "'")) or any(c.isalnum() for c in s):
        return 0.0
    q = s[-1]
    single = q == "'"
    if '{' in s:
        if ':' in s:
            return -1.5
        if s.startswith(' '):
            if previous.rstrip().endswith(':'):
                return -1.8 if single else -1.07
            return -0.6
        return -0.55 if single else -0.35
    if s == '","':
        return -2.0
    if s.lstrip().startswith(','):
        if MAPPING_VALUE.search(history.rstrip() + ','):
            return -2.0
        return -1.8 if s.startswith(' ') else 0.0
    if s not in (q, ' ' + q, '\\' + q, ' \\' + q):
        return 0.0
    # Escaped source text uses the same boundary rules one quoting level down.
    if '\\' in s:
        history = history.replace('\\' + q, q)
    tail = history.rstrip()
    before, content, after = previous_string(tail, q)
    mapping_string = after == ',' and before.endswith((':', '=>'))
    mapping_expression = bool(MAPPING_VALUE.search(tail))
    indented = previous.isspace() or '\n' in previous
    if tail.endswith(','):
        if mapping_string:
            strength = max(1.7, 4.0 - 0.01 * len(content))
            return -min(strength, 2.5) if indented else -strength
        if mapping_expression:
            return -2.5 if indented else -3.5
        if tail.endswith('},') or (tail.endswith('],') and q in previous):
            return -2.2
        if indented:
            return -2.5 if single or not s.startswith(' ') else -0.25
        if q in previous:
            return -0.85 if single else -0.4
    if indented:
        # Ignore a diff's added/deleted-line sign before a quoted code field.
        end = re.sub(r'[+-]\s*$', '', tail).rstrip()
        block_opener = bool(re.search(r'[()]\s*\{$', end))
        if end.endswith('{') and not block_opener:
            return -2.4
        if single and (end.endswith('[') or re.search(r'\barray\($', end)):
            return -2.0
        if re.search(r'(?:\\n|\n\s*\d+\t)\s*$', history):
            return -1.2
        if tail.endswith(('"', "'")):
            return -1.1
    if tail.endswith('{') and not re.search(r'[()]\s*\{$', tail):
        return -2.2 if single else -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous = '', ''
    else:
        _, history, previous = carry
    s = prefix.token_strings[-1]
    value = predict(s, previous, history)
    return (doc, (history + s)[-2048:], s), value

programs.haiku:
"""Opening quote of a dictionary / JSON key (negative activation).

This component of layer 1's MLP goes negative on the quote character that opens a new
KEY inside an object literal {...}, as in JSON or a Python dict:

  * after the comma between two entries:   {"name": "bash", "arguments"  <- the ' "' before arguments
  * right after the opening brace:         {"type"
  * at the start of an indented line:      "end": 14,\n    "rules"       <- the indented quote
  * an object opened as a value:           "arguments": {"command"       <- weaker: the ' {"' token

The size depends on the setting. Inside tool-call JSON (a '<tool' tag such as <tool_call>
or <tools> earlier in the same document) keys after a comma are strongest, about -3.8;
in ordinary JSON or Python dicts about -2.9. A comma-led quote only counts once that
object has shown a "key:" colon, so C/Java array initialisers like {"cow", "moo"} stay
near zero. Quotes that open a value (after ':') and string items inside [...] lists or
(...) calls are also near zero. An indented quoted string outside any object gives a
weak -0.6.

Everything else predicts 0. The program tracks the open brackets, whether each open
object has shown a colon, and the tool flag over the row, and resets them at each
document boundary.
"""

READS = ()

TOOL_VALUE = {"comma": -3.8, "brace": -3.7, "indent": -1.5, "object": -1.1}
PLAIN_VALUE = {"comma": -2.9, "brace": -1.4, "indent": -1.6, "object": -0.5}
INDENT_OUTSIDE_OBJECT = -0.6


def _opens_string(token):
    # a short token that starts a quoted string: optional space, brace, bracket, backslash, then a quote
    core = token.replace("{", "").replace("[", "").replace("(", "").replace("\\", "").strip()
    return core[:1] in ('"', "'") and len(token) <= 6


def step(carry, prefix, upstream):
    # stack: open brackets as (char, object_has_shown_a_colon); in_tool: a tool tag was seen
    stack, in_tool = carry if carry else ([], False)
    token = prefix.token_strings[-1]
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        stack, in_tool = [], False
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    last = before.rstrip()[-1:]
    indented = before != "" and before.strip() == ""
    table = TOOL_VALUE if in_tool else PLAIN_VALUE
    inside_object = bool(stack) and stack[-1][0] == "{"
    value = 0.0
    if _opens_string(token):
        if inside_object:
            if token.lstrip().startswith("{") and last == ":":
                value = table["object"]
            elif last == ",":
                value = table["comma"] if stack[-1][1] else 0.0
            elif last == "{":
                value = table["brace"]
            elif indented:
                value = table["indent"]
        elif indented and not in_tool:
            value = INDENT_OUTSIDE_OBJECT
    if token.startswith("<tool"):
        in_tool = True
    if inside_object and ":" in token:
        stack[-1] = ("{", True)
    for ch in token:
        if ch in "{[(":
            stack.append((ch, False))
        elif ch in "}])" and stack:
            stack.pop()
    return (stack, in_tool), value

programs.sol:
"""Predict reactions to reference openings and word-alternative separators.

HTTP(S) address separators are negative, especially HTTPS; Markdown anchors
and citation openings are positive. A prose heuristic picks out word-joining
slashes while rejecting many paths and units. Smaller rules cover LaTeX math
versus reference openings, Mathematica lists, and the phrase 'answer choice'.
The HTTP response is weaker near Han characters.
A bounded text suffix is retained and reset at document boundaries.
"""
import re
import regex
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=4096)
def familiar_word(word):
    return zipf_frequency(word.lower(), 'en') >= 2.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = -0.002

    if token == '://':
        if before.lower().endswith('https'):
            value = -1.82
        elif before.lower().endswith('http'):
            value = -1.03
            if regex.search(r'\p{Script=Han}', before[-14:]):
                value = -0.60
        else:
            value = -0.12
    elif token == '#' and before.endswith(('](', '){')):
        value = 1.10
    elif token == '[@' and before.endswith('['):
        value = 0.95
    elif token == '{':
        command = re.search(r'\\([A-Za-z]+)$', before)
        if command:
            name = command.group(1)
            if re.fullmatch(r'cite[a-z]*|link|url|code', name):
                value = 0.82
            elif name == 'ref':
                value = 0.21
            elif name in ('begin', 'end'):
                value = -0.24
            elif name in ('frac', 'dfrac', 'tfrac'):
                value = -0.14
    elif token == '["' and before.endswith('List'):
        value = -1.60
    elif (token.lower() in (' choice', ' choices')
          and before.lower().endswith('answer')):
        value = -1.5 if token.lower() == ' choice' else -2.5
    elif token.startswith('/') and (token == '/' or token[1:].isalpha()):
        word = re.search(r'[A-Za-z]+$', before)
        span = re.search(r'\S*$', before).group()
        if word and len(word.group()) >= 3 and familiar_word(word.group()):
            context = before[:-len(word.group())].rsplit('\n', 1)[-1][-90:]
            prose = len(re.findall(r' [a-zA-Z]{2,}', context)) >= 3
            path_or_code = re.search(r'[/._@:\\]', span) or re.search(
                r'[_=<>`]|//|--|&&| {3,}|\S/|\b(?:git|grep|cd)\b', context)
            unit = re.fullmatch(r'[numk]?(?:mol|grams?|metres?|meters?|units?)',
                                word.group(), re.I)
            if (prose and not path_or_code and not unit
                    and not word.group().isupper()):
                value = 0.80
        if token == '/or' and before.endswith('and'):
            value = 0.24
    elif token == 'www' and before.endswith('://'):
        value = -0.45 if before.lower().endswith('https://') else 0.15

    return (doc, (before + token)[-300:]), value

"""A first-token effect, strongest for opening notation and variable markers.

Reset at each document. At its first token, recognize whitespace, numbers,
opening/closing punctuation, and word shape. Ordinary words get a modest
frequency-based estimate; all later positions are approximated by zero.
The numbers are rounded training estimates. Individual word-specific
values and the small, variable later-token activations are not modeled.
"""
import regex
from wordfreq import zipf_frequency

READS = ()


def opening_value(s):
    w = s.strip()
    spaced = s.startswith(' ')
    if not w:
        if s == '\t':
            return 2.37
        if '\n' in s:
            return 0.0
        return 0.2 if len(s) == 1 else -0.85
    if w == '$':
        return 14.74 if spaced else 8.61
    if w.startswith('#!'):
        return 4.4
    if w.startswith('/*') and '\n' in s:
        return 3.9
    if w.startswith(('"""', "'''")):
        return 3.5
    if w.startswith(('()', '[]')):
        return -0.4
    if w[0] in '([（【「':
        return 6.1 if spaced else 2.6
    if w == '{':
        return -1.0 if '\n' in s else 1.9
    if w[0] in ')]}）】」':
        return -0.6
    if w == ':=':
        return 6.4
    if w == '=':
        return 3.8 if spaced else 1.9
    if w[0] == '\\':
        return 4.1 if spaced else 1.6
    if w[0] in '\'"':
        return 2.3 if spaced else -1.2
    if w[0] in '“‘¿':
        return 2.7
    if w == '<':
        return 4.0
    if w[0] == ';':
        return -1.3
    if w[0] == '.':
        return -3.0 if spaced else -0.1
    if w[0] == ',':
        return -0.24
    if w[0] == ':':
        return 0.6
    return 0.0


def word_value(s):
    w = s.strip()
    if w.isdigit():
        return -0.41
    if regex.search(r'\p{Script=Han}', w):
        return 1.25
    if regex.fullmatch('[A-Za-z]+', w):
        return (0.14 + 0.60 * s.startswith(' ') + 0.36 * w.istitle()
                - 0.33 * max(0.0, zipf_frequency(w.lower(), 'en') - 4))
    return 0.2


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry == document:
        return document, 0.0
    s = prefix.token_strings[-1]
    if s.startswith('<|'):
        value = 0.23
    elif not any(c.isalnum() for c in s):
        value = opening_value(s)
    else:
        value = word_value(s)
    return document, float(value)

"""Predict English reconsideration and elaboration constructions.

Word classes leave cues fading by 20% per token; refinement words and familiar
explanatory phrases modify their effects. Use character-based defaults at each
document start, and a large positive value for the colon of initial 'Title:'.
This captures constructions, not all token-specific variation.
"""
READS = ()

REFLECTION = frozenset(
    'wait think thought perhaps maybe mistake mistakes wrong error errors '
    'confusion understand check confirm verify reconsider'.split())
REQUESTS = frozenset(
    'guide trace research explain describe answer ask read write provide show '
    'demonstrate justify clarify substantiate analyze examine look review '
    'discuss determine'.split())
TOPICS = frozenset(
    'facts definitions statements outline cases test code context detail '
    'information problem problems question questions issue issues description '
    'statement response answer reasoning analysis explanation instructions '
    'transcript passage text'.split())
ARTICLES = frozenset('a an the this these those such each any some all'.split())
REFINEMENT = {
    'more': 0.077, 'better': 0.007, 'again': -0.039,
    'carefully': -0.087, 'further': 0.109,
}
# Word class, ordinary effect, additional effect on refinement words.
CUES = (
    (REFLECTION, -0.049, -0.242),
    (REQUESTS, -0.030, -0.143),
    (TOPICS, -0.041, -0.250),
    (frozenset(('i', 'me', "let's")), -0.029, -0.186),
    (frozenset(('following', 'above', 'below')),
     -0.044, 0.053),
)


def beginning(token):
    word = token.strip()
    if token == 'Title':
        return -0.475
    if token.startswith('<|'):
        return -0.136
    if token == '\t':
        return -0.550
    if token == '\r':
        return -0.819
    if not word:
        return -0.047
    if not word.isascii():
        return -0.229
    if word.isalpha():
        if len(word) <= 3:
            return -0.080
        if token.startswith(' ') or word[0].isupper():
            return -0.250
        return -0.103
    return 0.0 if word.isdigit() else 0.023


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('-')
    if carry is None or carry[0] != doc:
        position, traces, title, previous = 0, (0.0,) * 5, token == 'Title', ''
    else:
        _, position, traces, title, previous = carry

    reflective, request, topic, first_person, _ = traces
    english = bool(word) and word.isascii() and word.isalpha()
    value = 0.001
    if english:
        value += 0.011 if token.startswith(' ') else 0.002
    if '\n' in token or '\r' in token:
        value -= 0.006
    if any(ord(c) > 127 for c in word):
        value += 0.009
    if word in REFLECTION:
        value -= 0.021
    if word in REQUESTS:
        value -= 0.016
    if word in REFINEMENT:
        value += REFINEMENT[word]
    if english:
        for strength, (_, ordinary, extra) in zip(traces, CUES):
            value += strength * (ordinary +
                                 (extra if word in REFINEMENT else 0.0))

    if word == 'based':
        value -= 0.156 * max(topic, request)
    if word == 'process' and previous in ('thought', 'reasoning'):
        value -= 0.360
    if word == 'sure' and previous == 'make':
        value -= 0.110 + 0.058 * max(reflective, first_person)
    if word == 'through' and previous in (
            'go', 'guide', 'trace', 'walk', 'work'):
        value -= 0.155 + 0.209 * max(reflective, first_person)
    if word == 'format' and previous in (
            'markdown', 'json', 'following', 'output'):
        value -= 0.166
    if word == 'more':
        if previous in ARTICLES:
            value -= 0.185
        if previous == 'once':
            value -= 0.167

    if position == 0:
        value = beginning(token)
    elif position == 1 and title and token == ':':
        value = 7.170
    traces = tuple(1.0 if word in words else strength * 0.8
                   for strength, (words, _, _) in zip(traces, CUES))
    return (doc, position + 1, traces, title, word), float(value)

"""Approximate a detector of text-encoding and escaping artifacts.

Hexadecimal byte escapes, HTML entities and common mojibake are strong
signals. Escaped whitespace/quotes, TeX formatting and unusual text marks
are weaker signals. A separate rule recognizes a document-opening Title:
label. English function words help distinguish mojibake from accented words.
History is limited to 160 characters and resets at document boundaries.
