import re
from html.entities import name2codepoint

READS = ()

# TeX names and token-split pieces, grouped by typesetting role.
DELIMITERS = {'left': 1.28, 'right': .38}
TYPESETTING = {'text', 'mathrm', 'operator', 'phant', 'rule', 'big'}
MATH_STYLE = {'math', 'cal', 'bb', 'display', 'var', 'hat', 'wid', 'ilde'}
ENGLISH = re.compile(
    r'\b(the|and|this|that|which|your|with|have|from|because|is|are|not|can)\b',
    re.IGNORECASE,
)


def predict(s, b, old):
    if s == ':' and old == 'Title':
        return 19.5
    if s.endswith('&#'):
        return 6.2
    # Shared UTF-8 prefix of General Punctuation (spaces, quotes, dashes).
    if b.endswith(b'\xe2\x80'):
        return 1.8 if s.startswith(' ') else 3.1
