        # These isolated Latin-1 letters often introduce misdecoded UTF-8.
        if s.strip() == 'â':
            if s.startswith(' '):
                return 5.9
            return 7.5 if ENGLISH.search(old) or 'â€' in old or 'â‰' in old else 0.
        return 4.0 if s.strip() == 'Ã' else 1.7
    if old.endswith('â'):
