    if s == '\x92':
        return 2.3
    if s == '\\' and old.endswith(('\\n', '\\t')):
        return -2.5

    escaped = s[s.rfind('\\') + 1:] if '\\' in s else s if old.endswith('\\') else None
    if escaped is not None:
        slash_here = '\\' in s
        if re.fullmatch(r'x[0-9a-fA-F]*', escaped):
            if escaped.startswith('xe'):
                if not slash_here:
                    return 11.2 if len(escaped) == 2 else 6.4
                return 4.1 if re.search(r'\\x[0-9a-fA-F]{2}$', old) else 7.4
            if escaped.startswith('xc'):
                return 3.5 if slash_here else 8.7
            if escaped.startswith('xa'):
                return 2.25
            if escaped.startswith('xb'):
                return 3.2
            return 2.3 if slash_here else 1.8
        if re.fullmatch(r'u[0-9a-fA-F]*', escaped):
            return 3.1 if slash_here else 6.8
        if escaped == 'n':
            return 1.03 if slash_here else .70
        if escaped == 't':
            return .83 if old.endswith('\\t') else 1.25
        if escaped == 'r':
            return 1.0 if slash_here else 2.6
        if escaped == "'" and s == "\\'":
            return 8.0 if old[-1:].isalpha() and ENGLISH.search(old) else 3.8
        if escaped.startswith('"'):
            if len(escaped) > 1:
                return .32
            if s.startswith('('):
                return 1.17
            if s.startswith(' '):
                return 1.47
            return 2.8 if old.endswith(('(f', '!(')) else .85
        if escaped == '/':
            return 1.3
        if escaped == '$':
            return .57
        if escaped in DELIMITERS:
            return DELIMITERS[escaped]
        if escaped in TYPESETTING:
            return 1.15
        if escaped in MATH_STYLE:
            return .75
        if s and set(s) == {'\\'} and len(s) > 1:
            return .75
        if s == ' \\':
            prose = '\\n' in old and not any(c in old[-40:] for c in '{};$=')
