        if s in name2codepoint:
            return 1.5
    if s.startswith('&') and s[1:] in name2codepoint:
        return 1.7
    if s.strip() in {'`', '``'}:
        return .85 if '` `' in old[-32:] or '\xa0' in old[-32:] else .04
    if s and set(s) == {'·'} and len(s) > 1:
        return 1.37
    if s == '\xa0':
        return .18
    if s == '\x00':
        return 1.34
    if s == '\r':
        return .53
    if s == '‐':
        return .3
    if s == 'ّ':
        return .87
    return 0.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    value = predict(s, prefix.token_bytes[-1], old)
    return (doc, (old + s)[-160:]), value

