import re

READS = ()

# Whole temporal connectives; weights reflect their different strengths.
CONNECTIVES = {
    'when': -1.6, 'whenever': -3.6, 'while': -.45, 'whilst': -.5,
    'after': -.62, 'before': -.45, 'during': -1.1,
    'until': -.35, 'once': -.32, 'where': -.17, 'anytime': -3.8,
    'quand': -9., 'lorsque': -6., 'cuando': -5.7, 'quando': -4.5,
    'когда': -3.4, 'при': -1.3, 'kiedy': -5.7, 'gdy': -6.8,
    'kdy': -8., 'keď': -5., 'när': -6.6, 'når': -4.6,
    'wenn': -1.7, 'bei': -1.28, 'khi': -1.9,
}
TIME_NOUNS = set('time times day days year years age period moment '
                 'point date occasion hour month season era periods moments nights '
                 'century centuries'.split())
OCCURRENCES = {
    'every': -10.2, 'each': -8.5, 'next': -4.6, 'any': -6.9,
    'last': -2.5, 'second': -1., 'third': -1.5, 'that': -.8,
}
CLAUSE_LINKS = {
    'that': -3.5, 'and': -3.3, 'but': -4., 'so': -3.7,
    'because': -4.3, 'then': -4.5, 'happens': -4.7, 'now': -5.,
}
