# are complete conjunctions or the stem just before their final letter.
FRAGMENTS = {
    'quand': -18.4, 'cuando': -14., 'quando': -13.5,
    'lorsqu': -14.5, 'lorsque': -14., 'когда': -8.5, 'kdy': -8.,
    'gdy': -12., 'khi': -8.8, 'når': -10., 'kiedy': -8.,
    'když': -8., 'keď': -5.5, 'när': -5.5, 'wenn': -5.8,
    'whenever': -3.8,
}
FRAGMENT_RE = re.compile(r'(?:^|\W)(' + '|'.join(FRAGMENTS) + r')$')


def predict(token, tail, previous, old_value):
    bare = token.strip().lstrip('.,:;!?"“”()[]')
    word = bare.lower()
    prev = previous.strip().lower()
    standalone = (not token[:1].isalnum() or not tail or
                  not tail[-1:].isalnum())
    value = CONNECTIVES.get(word, 0.) if standalone else 0.
    if standalone:
        if word == 'when':
            if bare.startswith('W'):
                value = -3.4
            elif prev in TIME_NOUNS or re.search(r'\b[12]\d{3}$', tail):
                value = .5
            elif prev in ('is', 'are', 'was', 'were', 'even', 'especially'):
                value = -.6
            elif prev in CLAUSE_LINKS:
                value = CLAUSE_LINKS[prev]
            elif previous.strip().endswith((',', ':', ';')):
                dated = re.search(r'\b[12]\d{3}\D{0,12}$', tail)
                value = 1. if dated else -2.7
            if not tail:
                value = 2.41 if bare.startswith('W') else -.55
        elif word == 'whenever' and bare.startswith('W'):
            value = -4.9
        elif word in ('quando', 'cuando', 'когда') and bare[:1].isupper():
            value *= 1.6
        elif word == 'time':
            value = OCCURRENCES.get(prev, .15)
            if prev in ('every', 'each') and previous.strip().istitle():
                value -= 2.5
            if prev == 'each' and re.search(r'\b(at|for|in) each$', tail.lower()):
                value = -3.
            if prev == 'every' and re.search(r'\balmost every$', tail.lower()):
                value = -6.4
            if prev == 'any' and re.search(r'\bat any$', tail.lower()):
                value = -1.7
            if prev == 'first':
                ordinal = re.search(
                    r'\b(for|at) (the|a) (very )?first$', tail.lower())
                value = .35 if ordinal else -1.7
            if re.search(r'\bby the$', tail.lower()):
                new_clause = re.search(
                    r'\b(By|that by|so by|but by|since by) the$', tail)
                value = -9.7 if new_clause else -5.5
                if re.search(
                    r'\b(measured|multiplied|divided|given|influenced) by the$',
                    tail.lower(),
                ):
                    value = 0.
            elif re.search(r'\bat the$', tail.lower()):
                value = -.7
            elif re.search(r'\ball the$', tail.lower()):
                value = -.8
        elif word == 'as':
            value = {'soon': -5.96, 'long': -1.25}.get(prev, 0.)
        elif word == 'often':
            value = -1.3 if prev in ('so', 'more', 'how', 'very') else -.2
            if re.search(r'\bevery so$', tail.lower()):
                value = -4.5
        elif word == 'since' and prev == 'ever':
            value = -2.9
        elif word == 'then':
            value = {'but': -1.2, 'so': -.4}.get(prev, 0.)
        # A temporal marker can remain visible on the following pronoun.
        elif word in ('i', 'you', 'we'):
