        boundary = not tail or tail[-1] in '，。！？:：;；\n'
        value = -3.1 if boundary else -1.
    elif token in ('当我', '當我', '每次'):
        value = -4.2 if token != '每次' else -2.7
    if (tail + token).endswith('เมื่'):
        value = -10.7
    elif (tail + token).endswith('เมื่อ'):
        value = -6.5
    if not standalone or not value:
        match = FRAGMENT_RE.search((tail + token).lower())
        if match and word != match[1]:
            value = FRAGMENTS[match[1]]
