def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous, old_value = '', '', 0.
    else:
        _, tail, previous, old_value = carry
    token = prefix.token_strings[-1]
    value = predict(token, tail, previous, old_value)
    return (doc, (tail + token)[-100:], token, value), value

