"""Temporal clause openers.

The component goes negative on the word that opens a clause of time: "When I ...",
"By the time ...", "As soon as ...", "every time ...", and on the same word in other
languages (cuando, quand, när, когда, khi, ...). The subject right after a clause-opening
"when" ("when I", "when we") is also negative. A relative "when" after a time noun ("the day
when ...") is near zero or slightly positive. Prepositions of time (during, after, before,
while, until) are weakly negative.
"""

READS = ()

WHEN_ENGLISH = {"when", "whenever"}
# when-words in other languages, by how strongly they open a time clause
WHEN_STRONG = {"cuando", "quando", "quand", "lorsque", "lorsqu", "när", "når"}
WHEN_MEDIUM = {"когда", "khi", "当", "當", "عندما", "kiedy", "když", "kdy", "ketika", "amikor"}
WHEN_WEAK = {"wenn", "kun"}
# weak negative for temporal prepositions and conjunctions
WEAK = {"during": -1.1, "after": -0.6, "before": -0.4, "while": -0.4, "until": -0.35,
        "once": -0.3, "upon": -0.2, "bei": -1.3, "при": -1.3}
# the subject that follows "when": "when I", "when we", "when you"
SUBJECT = {"i": -2.5, "we": -1.5, "you": -1.1}
TIME_NOUNS = {"time", "times", "day", "days", "year", "years", "night", "nights", "moment",
              "week", "month"}
# words after which a new clause starts
BOUNDARY = {"|", ".", "!", "?", ":", ";", '"', "*", "-", "(", "and", "but", "so", "or", "then",
            "that", "yet"}
WHEN_ALL = WHEN_ENGLISH | WHEN_STRONG | WHEN_MEDIUM | WHEN_WEAK


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    hist = carry if carry is not None and not new_doc else ()
    body = s.strip().lower() if s.strip() else "|"
    # a token without a leading space that follows a word continues that word
    if hist and s[:1].isalpha() and hist[-1].isalpha():
        hist = hist[:-1] + (hist[-1] + body,)
    else:
        hist = hist + (body,)
    hist = hist[-4:]
    cur = hist[-1]
    prev = hist[-2] if len(hist) > 1 else "|"
    before = hist[-3] if len(hist) > 2 else "|"
    if cur in WHEN_ENGLISH:
        if prev in TIME_NOUNS:
            value = 1.5          # relative "when": "the day when ..."
        elif prev == ",":
            value = -2.0         # "..., when ..."
        elif prev in BOUNDARY:
            value = -3.8         # clause-initial "When ..."
        else:
            value = -2.0         # "happens when", "only when"
    elif cur in WHEN_STRONG:
        value = -6.0
    elif cur in WHEN_MEDIUM:
        value = -3.0
    elif cur in WHEN_WEAK:
        value = -1.5
    elif cur == "time" and prev in ("every", "each"):
        value = -9.0
    elif cur == "time" and prev == "next":
        value = -5.0
    elif cur == "time" and prev in ("last", "any"):
        value = -2.5
    elif cur == "time" and prev == "the" and before == "by":
        value = -8.0             # "by the time ..."
    elif cur == "as" and prev == "soon":
        value = -7.0             # "as soon as ..."
    elif prev in WHEN_ALL and cur in SUBJECT:
        value = SUBJECT[cur]     # the subject after a clause-opening "when"
    elif cur in WEAK:
        value = WEAK[cur]
    else:
        value = 0.0
    return hist, value

