"""Sparse spelling cues, especially at splits inside abbreviations and units.

MP3/MP4, pressure units, and a few other split initialisms give negative
values. The English word mumps and a word-initial Arabic mim give positive
values. Japanese 彼 and the minus following a diff's @@ are negative.
Most positions are left at zero. These are approximate lexical rules, not
an assertion that all abbreviations or all Arabic participles behave alike.
"""
import regex

READS = ()
SI_PREFIXES = frozenset('qryzafpnumcdhkMGTPEZYRQμµ')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    state = (doc, token)
    initial = previous.lstrip(' \t./_(-')

    # Media-file extensions MP3/MP4 and the pressure symbol MPa.
    if initial.lower() == 'mp' and token in ('3', '4', 'a'):
        return state, -7.0
    if previous == '@@' and token == ' -':
        return state, -1.4

    # Split unit symbols with metric or binary prefixes (and PVA).
    if token.lower() == 'pa' and initial in SI_PREFIXES:
        if initial == 'M':
            return state, -5.5
        return state, -3.5 if initial == 'k' else -1.4
    if token == 'Pa' and previous.isdigit():
        return state, -1.2
    if token == 'VA' and initial in ('k', 'M', 'P'):
        return state, -3.0
    if token == 'Da' and initial == 'k':
        return state, -1.5
    if token == 'bytes' and initial in ('k', 'K', 'M', 'G'):
        return state, -2.5
    if token == 'B' and initial in ('Ki', 'Mi', 'Gi'):
        return state, -4.5
    if token == 'pc' and initial in ('k', 'M', 'G'):
        return state, -2.5
    if token == 'π' and initial in ('k', 'μ', 'µ'):
        return state, -1.5 if initial == 'k' else -3.5

    # Particular split initialisms: KPI, MMPI, PIA, and PIB.
    if token == 'PI' and initial in ('K', 'MM'):
        return state, -5.8 if initial == 'K' else -3.9
    if initial == 'P' and token in ('IA', 'IB'):
        return state, -2.0

    if initial.lower() == 'm' and token == 'umps':
        return state, 6.5
    # A boundary is important: bare mim inside a word is not this prefix.
    if previous in (' م', ' الم') and regex.fullmatch(r'\p{Script=Arabic}+', token):
        return state, 0.5
    if token == '彼':
        return state, -2.5
    if token == '匹' and previous.isdigit():  # Chinese animal counter.
        return state, -3.5
    if token == ' views' and previous.isdigit():
        return state, -1.5
    if not previous and token == 'def':
        return state, -2.4
    return state, 0.0

