"""A local spelling heuristic for number-bearing names and abbreviations.

ASCII digits near short capital-heavy letter strings receive positive values;
continued digits usually receive more than the first digit. Hyphens, capitalized
hyphen suffixes, and some spaces after abbreviations also receive positives.
Ordinary numbers stay near zero. Unary negatives, further numeric fields, and
opaque mixed-case data are treated conservatively. Byte escapes get a small
negative value. No token-ID lookup is used.
"""
import regex as re

READS = ()
LETTERS_AND_DIGITS = r'[\p{Cased_Letter}0-9]+'


def capitals(text):
    return sum(c.isupper() for c in text)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0)
    _, history, previous_caps, older_caps = carry
    token = prefix.token_strings[-1]
    match = re.search(LETTERS_AND_DIGITS + '$', history)
    word = match[0] if match else ''
    caps = capitals(word)
    value = -0.002

    if token.isascii() and token.isdigit():
        match = re.search(r'[0-9]+$', history)
        run = len(match[0]) if match else 0
        before = history[:-run] if run else history
        boundary = before[-1:]
        match = re.search(LETTERS_AND_DIGITS + r'[\W_]*$', before)
        name = re.match(LETTERS_AND_DIGITS, match[0])[0] if match else ''
        name_caps = capitals(name)
        name_lower = sum(c.islower() for c in name)
        name_digits = sum(c.isdigit() for c in name)
        word_digits = sum(c.isdigit() for c in word)

        if re.search(r'\\x[0-9a-fA-F]?$', history):
            value = -0.18  # A byte escape, not a numbered name.
        elif boundary == '-' and (
                not before[-2:-1].isalnum() or name_digits >= 3):
            value = -0.002
        elif boundary.isupper():
            if run:
                value = 2.14 if caps >= 2 else 1.17
            elif caps >= 2:
                value = 0.26 if word_digits else 1.15
            else:
                value = 0.17
        elif boundary == '-' and name_caps:
            value = 2.07 if name_caps >= 2 else (1.71 if run else 0.64)
        elif name_caps >= 2:
            if name_caps <= 4 and name_lower <= 3:
                if older_caps >= 2:
                    value = 1.13 if history[-1:].isspace() else 0.40
                else:
                    value = 0.46 if run else 0.14
        elif boundary.islower():
            value = (0.20 if name_digits else 0.73) if run else 0.07
        elif name_caps == 1:
            value = 0.06

        # Random-looking interleavings of case and digits are often opaque data.
        if (len(word) >= 9 and caps >= 2 and word_digits
                and sum(c.islower() for c in word) >= 2):
            value *= 0.1
    elif caps >= 2:
        if token.startswith('-'):
            if len(token) <= 2:
                value = 1.19 if len(word) <= 3 else 0.70
            elif re.fullmatch(r'-[IVXLCDM]+', token):
                value = 2.5  # A Roman-numeral-like suffix.
            elif token[1:2].isupper() and not token[1:].isupper():
                value = 1.59
        elif token.isspace():
            value = 0.40 if len(word) <= 2 else 0.08

    return (doc, (history + token)[-120:], capitals(token), previous_caps), value

"""A sparse recognizer of qualified library names and fixed constructions.

Large negative values mark selected namespace/package boundaries, Python's
`from ... import`, and Wikipedia article paths. /usr/local is positive on
`local` and negative on its following directory. Smaller rules cover institution
names and code idioms. This is an approximation: unrecognized text gets zero.
The state is just recent text and the previous token, reset for each document.
"""
import re
import sys

READS = ()
# Scientific computing, data extraction, and associated utilities.
DATA_PYTHON = {
    'numpy', 'scipy', 'pandas', 'keras', 'PIL', 'torch', 'tensorflow',
    'sklearn', 'matplotlib', 'tqdm', 'bs4',
}
# Heads of institution names and academic titles taking an 'of' complement.
INSTITUTION_HEADS = {
    'University', 'College', 'Institute', 'School', 'Department', 'Academy',
    'Museum', 'Ministry', 'Republic', 'Union', 'Office', 'Professor',
}
RUST_MODULES = {
    'error', 'thread', 'path', 'array', 'io', 'iter', 'sync', 'fs', 'env', 'fmt',
}


def activation(before, token, previous):
    before = before.replace('\\n', '\n').replace('\\t', '\t')
    word = token.strip()
    match = re.search(r'[\w.]+$', before)
    name = match.group() if match else ''

    # Lower-case segments of package names, rather than class names.
    if name.islower() and re.fullmatch(r'\.[a-z][a-z_]*', token):
        member = token[1:]
        if name == 'android':
            if member in {'view', 'widget', 'graphics'}:
                return -12.9
            if member == 'os':
                return -11.5
            return -0.9 if member == 'support' else -4.8
        if name == 'android.view' and member == 'animation':
            return -11.2
        if name.startswith('androidx.'):
            if member == 'widget':
                return -11.0
            if member in {'app', 'util'}:
                return -6.5
        if name == 'java':
            if member in {'net', 'time'}:
                return -9.1
            if member in {'text', 'math', 'base'}:
                return -6.2
            if member in {'awt', 'swing'}:
                return -2.7
            return -4.6
        if name.startswith('java.'):
            if name == 'java.lang' and member == 'annotation':
                return -0.6
            if member in {'concurrent', 'function', 'event'}:
                return -9.8
            return -6.2
        if name == 'javax':
            return -2.5
        if name == 'com.google.common' and member == 'base':
            return -12.5
        if name == 'com.google.common.util' and member == 'concurrent':
            return -10.0
        if name == 'com.google.api':
            if member == 'client':
                return -3.7
            if member == 'core':
                return -7.0
        if name == 'com.google.api.client' and member == 'util':
            return -2.7
        if name.startswith('org.springframework'):
            if member in {'domain', 'env', 'servlet', 'factory'}:
                return -10.0
            if member in {'core', 'http'}:
                return -7.5
            return -3.0
        if re.search(r'\b(?:import|package) (?:static )?[\w.]+$', before):
            return -0.5
    if token == '\\Http' and before.endswith('\\Illuminate'):
        return -9.5
    if name == 'System' and token in {'.Threading', '.Net'}:
        return -6.0

    # The import keyword depends on the kind and depth of the module name.
    if token == ' import':
        match = re.search(r'\bfrom ([\w.]+)$', before)
        if match:
            module = match[1]
            root = module.split('.')[0]
            if root in sys.stdlib_module_names:
                return -7.4 if '.' not in module else -5.5
            if root in DATA_PYTHON:
                return -7.3 if module.count('.') < 2 else -3.0
            if root.startswith(('PyQt', 'PySide')):
                return -10.0
            if root in {'pymongo', 'sqlalchemy'}:
                return -7.0
            return -1.8
    if word == '::':
        if name == 'std':
            return -3.7
        if before.endswith('std::fmt'):
            return -2.5
    if before.endswith('std::'):
        if word in {'collections', 'cmp'}:
            return -8.5
        if word in RUST_MODULES:
            return -4.6 if word in {'io', 'fmt'} else -3.0
    if word == 'new' and before.endswith('::'):
        return -1.7

    # Conventional paths and a few common code idioms.
    if token == '/local' and before.endswith('/usr'):
        return 4.2
    if token in {'/bin', '/lib', '/go'} and before.endswith('/local'):
        return -3.2 if token == '/go' else -4.6
    if token == '/wiki' and before.endswith('wikipedia.org'):
        return -9.2
    if token in {'/docs', '/link', '/licenses'} and re.search(r'https?://\S+$', before):
        return -2.0
    if token == '/java' and before.endswith(('/test', '/main')):
        return -1.9
    if token == '_modules' and before.endswith('/node'):
        return -0.7
    if word == 'of' and previous.strip() in INSTITUTION_HEADS:
        return -2.7 if previous.strip() in {'College', 'Institute'} else -1.3
    if word == 'final' and previous.strip() in {'static', 'private', 'public'}:
        return -2.4
    if token.startswith('[]') and before.endswith('String'):
        return -2.2
    if token == '.stringify' and name == 'JSON':
        return -1.4
    if token == '.env' and name == 'process':
        return -2.7
    if token == ':' and (before == 'Title' or before.endswith('<|endoftext|>Title')):
        return -6.4
    if token and set(token) == {'·'} and len(token) >= 2:
        return 1.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, previous = '', ''
    else:
        _, before, previous = carry
    token = prefix.token_strings[-1]
    value = activation(before, token, previous)
    return (doc, (before + token)[-160:], token), value

programs.haiku:
"""Namespace paths (negative), and the Unix path /usr/local (positive).

A dotted or slashed name for a library, package or site is a path. The token that
continues it into a sub-package is negative:
  - in an import, use or from line of a well-known library, the first package step
    is strongly negative: the `.view` in `import android.view` (about -10), the
    `.util` in `import java.util` (about -6), the ` import` in `from datetime import`
    (about -6), the `::` in `use std::` (about -6);
  - a deeper package step is about -2, except in a few large namespaces (Spring,
    androidx, java.util, java.nio, ...) where it is as strong as the first step
    (the `.domain` in `org.springframework.data.domain`);
  - after a namespace word in code or a stack trace: the `.lang` after `java`, the
    `::` after `std`, the `Http` after `Illuminate` (about -5);
  - the `/wiki` in `en.wikipedia.org/wiki` (about -8), and the `/java` in a Maven
    `src/main/java` path (about -2.5).
Class names (`.Log`, `.Arrays`) are not packages and stay at zero. Two more fixed
tokens: the `local` in `/usr/local` is about +4, and the `/bin` or `/lib` after it is
about -4. Also, the `of` in `University of` (after an organisation noun) is about -1.5,
and the word after `National` (`National Park`) is about +1.5. Everything else is zero.
"""
import re

READS = ()

# Well-known libraries and namespaces whose sub-packages the model expects.
LIBRARY_ROOTS = frozenset({
    "android", "androidx", "java", "javax", "std", "Illuminate", "org.springframework",
    "com.google", "typing", "datetime", "collections", "enum", "tqdm", "flask", "scipy",
    "tkinter", "math", "django", "bs4", "time", "urllib", "keras", "sklearn", "nltk",
    "PIL", "rich", "tensorflow", "__future__", "rest_framework",
})
# Large namespaces whose deeper package steps are as strong as the first step.
STRONG_NAMESPACES = ("org.springframework", "androidx", "javafx", "javax.swing",
                     "java.util", "java.nio", "java.awt", "com.google.common")
# Words that name a package or namespace when they stand alone in code.
NAMESPACE_WORDS = frozenset({" java", "java", " android", "android", " std", "std",
                             "\tstd", "Illuminate", "nio", "lang", "util"})
ORGANISATION_NOUNS = frozenset({" University", " College", " Institute", " Department",
    " Republic", " School", " Academy", " Union", " Society", " Ministry", " Museum",
    " Bureau", " Faculty", " Office", " Kingdom", " Council", " Committee"})
# An import, use or from line up to the current token; a literal "\n" in escaped code counts.
STATEMENT = re.compile(r"(?:^|[\s;>]|\\n)(import|from|use)\s+([A-Za-z_][\w.:\\]*)$")
LINE_TAIL = 24


def is_library(path):
    """True if `path` is a library name, or a path below one, like `java.util`."""
    return any(path == root or path.startswith((root + ".", root + "::", root + "\\"))
               for root in LIBRARY_ROOTS)


def line_before(tokens):
    """The text since the last newline, before the current (last) token."""
    line = ""
    for s in reversed(tokens[-LINE_TAIL:-1]):
        if "\n" in s:
            return s.split("\n")[-1] + line
        line = s + line
    return line


def import_step(keyword, path, cur):
    """The activation of `cur` inside an import, use or from line naming `path`."""
    if keyword == "from" and cur == " import":
        return -6.0 if is_library(path) else -2.5
    if not is_library(path) or cur[1:2].isupper():
        return 0.0  # not a library, or a class name such as `.Log`
    if cur[:1] not in (".", ":", "\\") and not (cur[:1].islower() and path.endswith(("::", "\\"))):
        return 0.0
    if "." in path or "::" in path or "\\" in path:
        return -6.0 if path.startswith(STRONG_NAMESPACES) else -2.0
    return -10.0 if path == "android" else -6.0


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    cur = tokens[-1]
    prev = tokens[-2] if len(tokens) > 1 else ""
    if cur == "/local" and prev.endswith("usr"):
        return carry, 4.0
    if cur in ("/bin", "/lib") and prev == "/local":
        return carry, -4.0
    if cur == "/wiki" and prev == ".org":
        return carry, -8.0
    if cur == "/java" and prev in ("/main", "/test"):
        return carry, -2.5
    m = STATEMENT.search(line_before(tokens))
    if m is not None:
        return carry, import_step(m.group(1), m.group(2), cur)
    if cur[:1] in (".", ":", "\\") and prev in NAMESPACE_WORDS:
        return carry, -5.0
    if cur == " of" and prev in ORGANISATION_NOUNS:
        return carry, -1.5
    if prev == " National" and cur[1:2].isupper():
        return carry, 1.5
    return carry, 0.0

