"""Rare document-opening patterns, especially the colon in initial ``Title:``.

The largest response is to the second token of a document beginning ``Title:``;
initial ``12`` is a smaller positive trigger.  Code/markup openings, escaped
quotes, question/upload headings and date headers have smaller responses.
Away from these openings
this approximation is mostly silent.  Exceptions are repeated opening layout
markers and Chinese poem/song references: 首 after counters or demonstratives,
merged forms, and nearby poetry/music vocabulary.  There is a small default
offset on the first token.  Many small lexical responses remain unmodeled.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, first, opening_run, tail = 0, token, True, ""
    else:
        _, position, first, opening_run, tail = carry
    opening_run = opening_run and token == first

    value = 0.0
    if position == 0:
        value = 0.1
        if token == 'Title':
            value = -1.265
        elif token == '#ifndef':
            value = 2.155
        elif token == '#define':
            value = 1.31
        elif token == '#include':
            value = 0.715
        elif token == '\\"':
            value = 2.195
        elif token == '<!':
            value = 2.056
        elif token.strip() == '"':
            value = 0.8
        elif token == 'Question':
            value = 0.98
        elif token == 'uploaded':
            value = 1.87
        elif token == 'question':
            value = 1.79
    elif position == 1:
        if first == 'Title' and token == ':':
            value = 11.622
        elif first == '1' and token == '2':
            value = 3.087
        elif first == 'Posted' and token == ' on':
            value = 2.18
    elif position == 2 and first == '1' and tail == '12' and token == '2':
        value = 1.315

    # 首 is a counter for poems and songs, but also means "head/first".
    if token == '首':
        if position == 0:
            value = 1.406
        elif tail and tail[-1] in '一二三四五六七八九十两兩几幾这這那':
            value = 2.3
        elif any(word in tail for word in ('诗', '詩', '歌', '曲')):
            value = 1.0
    elif token in ('一首', '这首', '這首'):
        value = 0.6
    elif token in ('诗', '詩') and tail.endswith(('首', '古', '这', '這')):
        value = 0.65

    if opening_run:
        if len(token) >= 2 and set(token) == {'·'}:
            value = 1.074
        elif len(token) >= 4 and set(token) == {'^'}:
            value = 2.07
        elif token == '\\t':
            value = 1.855
        elif token == '\\n':
            value = 1.013
    return (doc, position + 1, first, opening_run, (tail + token)[-16:]), value

"""Approximate the negative pulse before a document has varied token context.

Keep the pulse while the prefix contains only one distinct token. Its magnitude
uses token length, case, spacing, grammatical classes and punctuation shape;
escaped controls are especially strong. After the first different token,
predict silence. Broad classes leave individual-word variation unexplained.
"""
import re
import wordnet

READS = ()
PRONOUNS = frozenset('''
    i we you he she it they me us him her them my our your his its their
    mine ours yours hers theirs myself yourself himself herself itself
    ourselves yourselves themselves
'''.split())
CONJUNCTIONS = frozenset('''
    and or but nor yet so if because although while unless since whether
'''.split())


def initial_pulse(s):
    if s == '<|im_start|>':
        return -13.08
    if s.isspace():
        if s == ' ':
            return -0.11
        if '\t' in s:
            return -9.0
        if '\n' in s:
            return -2.4 if '\r' not in s else -7.0
        return -5.0
    word = s.strip()
