        return -2.4
    if re.fullmatch(r'(?:\\[nrt])+', word):
        return -19.5

    value = -3.3 - 0.27 * min(len(word), 20)
    if any(c.isalpha() for c in word):
        value -= 1.6
    if word and word[0].isupper():
        value -= 1.4
    if s.startswith(' '):
        value += 1.0
    lower = word.lower()
    if 'noun' in wordnet.parts_of_speech(lower):
        value += 1.1
    if lower in PRONOUNS:
        value -= 1.0
    if lower in CONJUNCTIONS:
        value += 1.1
    if (len(word) > 1 and len(set(word)) == 1
            and not word[0].isalnum()):
