import calendar
import re
import regex

READS = ()
MONTHS = {m.lower() for m in calendar.month_name if m}
MONTH_ABBREVIATIONS = {m.lower() for m in calendar.month_abbr if m}


def number_levels(before):
    left = before.rstrip()
    if not left:
        return (0.603, 0.652)
    c = left[-1]
    m = re.search(r'([^\W\d_]+)$', left)
    word = m.group().lower() if m else ''
    if word in MONTHS:
        return (1.33, 1.429)
    if word in MONTH_ABBREVIATIONS:
        return (0.9, 0.888)
    if word in {'born', 'copyright'} or c == '©':
        return (1.848, 1.863)
    if word in {
        'in', 'since', 'during', 'the', 'early', 'late', 'year', 'years'
    }:
        return (1.454, 1.596)
    if word in {'from', 'until', 'before', 'after', 'between'}:
        return (1.126, 1.448)
    if regex.match(r'\p{Script=Han}', c):
        return (1.253, 0.893)
    if c == '.' and len(left) > 1 and left[-2].isdigit():
        return (0.205, 0.344)
    if c in ',.':
        return (0.988, 1.131)
    if c in '(（':
        return (1.047, 1.359)
    if c in '-–—':
        return (0.509, 0.57)
    if c in '/:':
        return (0.626, 0.578)
    if c in '=[$£€\'"':
        return (0.286, 0.405)
    if before[-1:].isalpha():
        return (0.597, 0.61)
    return (0.645, 0.853)


def to_level(token, before):
    if token.strip() == 'To':
        if not before:
            return -0.276
        if before.endswith('\n') or before.rstrip()[-1:] in '.!?;:-•':
            return 1.275
        return 0.241
    if token.strip() == 'TO':
        return 0.155
    left = before.rstrip()
    if not left or before.endswith('\n'):
        return 0.086
    c = left[-1]
    if c in ',;:':
        return 0.894
    if c in '.!?':
        return 0.211
    if c in '-–—•':
        return 1.149
    if c in ')]':
        return 0.135
    if c in '(\'"“':
        return 0.263
    m = re.search(r'([A-Za-z]+)$', left)
    word = m.group().lower() if m else ''
    if token == 'to' and before[-1:].isalpha():
        return 0.27
    if word in {'and', 'or'}:
        return 2.02
    if word in {'but', 'so'}:
        return 1.604
    if word in {'is', 'are', 'was', 'were', 'be', 'been', 'being'}:
        return 0.918
    if word in {
        'as', 'if', 'that', 'then', 'than', 'whether', 'except', 'yet'
    }:
        return 0.996
    if word in {'not', 'never'}:
        return 0.991
    if word in {'just', 'simply', 'merely', 'also', 'even', 'rather', 'thus'}:
        return 0.83
    if word in {'what', 'which', 'where', 'when'}:
        return 0.646
    if word == 'order':
        return 0.355
    if word in {'seem', 'seems', 'seemed'}:
        return 0.403
    if word in {'mean', 'means', 'meant', 'aim', 'aims', 'aimed'}:
        return 0.639
    if word in {'more', 'less'}:
        return -0.591
    if word in {'nothing', 'something', 'anything', 'everything'}:
        return -0.42
