def predict(token, before):
    if token in ('0', '9'):
        m = re.search(r'[0-9]+$', before)
        digits = m.group() if m else ''
        if (token, digits) in {('0', '2'), ('9', '1')}:
            values = number_levels(before[:-1])
            return values[token == '9']
        if token == '0' and len(digits) > 1 and digits.endswith('2'):
            return -0.28 if len(digits) == 2 else -0.08
        return 0.0
    if token.strip().lower() == 'to':
        return to_level(token, before)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(token, before)
    return (doc, (before + token)[-160:]), value

