"""Layer-1 MLP down-projection component 2459.

What it does, in plain terms:
1. Year starts. It fires on the first two digits of a four-digit year that begins
   "19" or "20" (the "9" of "19xx", the "0" of "20xx"), when the number is written in
   running text. It is strongest when a cue such as a month name, "in", "from",
   "since", "born" or "the" sits just before the number, and weak when the number is
   indented or spaced out as in code or tables.
2. The word "to" after a clause-linking word. It fires on " to" / " To" when the word
   before it is a conjunction, punctuation or copula ("and to", "or to", "is to",
   "., to"), and not when "to" follows a verb or adjective that takes an infinitive
   ("need to", "want to", "used to", "able to"), where it stays near zero.

Everything else predicts 0. It needs no carried state: each step reads only the last
few tokens of the prefix.
"""

READS = ()

MONTHS = {"January", "February", "March", "April", "May", "June", "July", "August",
          "September", "October", "November", "December"}
YEAR_CUES = {"in", "from", "since", "born", "during", "until", "the", "of", "by"}

# Activation of "to" after each clause-linking word (roughly, per the sample).
TO_AFTER = {"and": 2.0, "or": 1.7, "but": 1.5, "so": 1.8, "never": 2.0, "if": 1.5,
            "that": 1.3, "then": 1.2, "while": 0.9, ".": 1.3, ";": 1.8, ":": 1.3,
            ",": 1.0, "is": 1.0, "was": 1.0, "were": 0.8, "are": 0.7, "as": 0.9,
            "not": 0.9, "just": 0.7, "also": 0.8, "like": 0.5, "order": 0.4,
            "seems": 0.4}


def year_digit(t, base):
    """t[-1] is the second digit of a number starting at t[-2] ("1" "9" or "2" "0")."""
    if len(t) < 3 or t[-3].isdigit():
        return 0.0  # the number has more digits before it, so it is not a year start
    if len(t) >= 4 and t[-3] == " " and t[-4].strip() == "":
        return 0.0  # indented or spaced-out numbers, as in code and tables
    before = [w.strip() for w in t[max(0, len(t) - 6):len(t) - 2]]
    cue = any(w in MONTHS or w in YEAR_CUES for w in before)
    return base * (1.4 if cue else 0.8)


def step(carry, prefix, upstream):
    t = prefix.token_strings
    if len(t) < 2:
        return carry, 0.0
    cur, raw, prev = t[-1], t[-2], t[-2].strip()
    if cur == "9" and raw == "1":
        return carry, year_digit(t, 1.0)
    if cur == "0" and raw == "2":
        return carry, year_digit(t, 0.8)
    if cur in (" to", " To"):
        return carry, TO_AFTER.get(prev, 0.0)
    return carry, 0.0

