AGE_UNITS = {'year', 'years', 'month', 'months', 'week', 'weeks',
             'day', 'days', 'hour', 'hours'}
DETERMINERS = {'a', 'an', 'the', 'this', 'that', 'these', 'those',
               'my', 'your', 'his', 'her', 'our', 'their', 'its'}
DEGREE_WORDS = {'too', 'very', 'quite', 'so', 'how', 'as', 'rather',
                'fairly', 'really', 'extremely'}


