        return 6.9
    if (tail + raw).endswith('老'.encode()) and '老' not in text:
        return 14.6
    if s.lstrip('的') == '老':
        return 9.2
    if s == '老人':  # the Chinese word for an old person
        return 3.6
    if '老' in s:
        return 1.5 if len(s) <= 2 else 0.8
    if low == 'old':
        before = previous.strip().lower().rsplit('-', 1)[-1]
        if before in AGE_UNITS or (s.islower() and before.isdigit()):
            return -0.2
        if not text[:1].isspace() and word:
            return 0.2
        if not text[:1].isspace():
            return 1.6
        if before in DETERMINERS:
            return 2.5
        if before in DEGREE_WORDS:
            return 1.2
        return 2.4 if s[:1].isupper() else 2.0
    if low == 'oldest':
        return 1.5
    if low == 'elderly':
        return 0.9
    if low == 'eldest':
        return 0.55
    if not text[:1].isspace():
        w = word.lower()
        if w == 'ol' and s in {"'", '’'}:
            return 6.8
        if w == 'ol' and low.startswith('d'):
            return 3.5
        if w.endswith('l') and low.startswith('ough'):
            return 6.2 if w == 'l' else 4.0 if len(w) <= 2 else 2.3
        if w == 'l' and low.startswith('ão'):
            return 9.8
        if w == 'ла' and low.startswith('о'):
            return 7.5
        if w == 'la' and low.startswith('o'):
            return 3.3
        if w == 'л' and low.startswith('ь'):
            return 2.4
        if w == 'о' and low.startswith('л'):
            return 2.0
        if w == 'o' and low.startswith('l') and len(low) > 1:
            return 0.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, word, tail = '', '', b''
