"""A rough academic-web-label and formatting detector, not a full reconstruction.

It emphasizes completed subject names in headings, homework/solution labels,
and the delimiters around questions. Ordinary lowercase uses can have the
opposite sign. Whitespace and repeated initial formatting have separate rules.
These patterns recur in high-importance training examples; they do not explain
most of the weak background lexical variation.
"""
import re

READS = ()
SCIENCES = set('physics chemistry biology'.split())
SUBJECTS = SCIENCES | set('''mathematics economics finance accounting management
engineering computer science statistics algebra'''.split())
CODE_WORDS = set('''package import using const function class namespace
from int void var let'''.split())


def initial(s):
    if s == ' ':
        return .504
    if s == '<!':
        return -3.67
    if s == '\0':
        return 3.61
    if s == '\r':
        return -3.34
    if s == '//\n':
        return -6.09
    if s.startswith('//'):
        return -.64
    if s.strip() and set(s.strip()) == {'/'}:
        return 2.30 if '\n' in s else -.15
    if s.strip() and set(s.strip()) == {'^'}:
        return -1.48 if len(s.strip()) >= 4 else -.26
    if s in ('#', '##', '###'):
        return -.8
    if s.strip() in CODE_WORDS:
        return -.7
    if s == '<|im_start|>':
        return .205
    if s.isspace():
        return .108
    if s.strip().isdigit():
        return .13
    if s.strip() in ('I', 'We', 'You', 'He', 'She', 'They', 'It'):
        return .24
    return -.003


def predict(s, before, position):
    if position == 0 or (before and before == s * position):
        return initial(s)
    if s == ' ':
        if position == 1 and before == ',':
            return 2.05
        if before.endswith(','):
            m = re.search(r'([A-Za-z]+)[.,]+$', before)
            if not m:
                return -.15
            word = m[1]
            if re.search(r'(?:^|\n)Mathematics,$', before):
                return 5.0
            if ' et al' in before[-80:] or '&' in before[-40:]:
                return .45
            if re.search(r'(?:[A-Z][A-Za-z]+[ .]+){2,}[.,]+$', before):
                return .25
            return -.05 if word.istitle() or word.isupper() else -.19
        return .044 if before.endswith('.') else -.002
    if s and set(s) == {'·'} and len(s) > 1:
        return .48
    if s == '<|im_end|>':
        return .046
    # Standalone heading labels, not every occurrence of "question".
    if re.search(r'(?:^|\n)[ #]*(?:Question|Related Questions)\s*$', before):
        if s.isspace() or ':' in s:
            return 1.8
        if s.strip('# ') == '':
            return 1.0
    if s.strip('# ') == '' and len(s.strip()) >= 5:
        if (re.search(r'\b(?:question|Question|Homework|Assignment)\b', before)
                or re.search(r'(?:\.{3}|…)\s*$', before)):
            return .55
    if not s or not s[-1].isascii() or not s[-1].isalpha():
        return -.003
    text = before + s
    m = re.search(r'[A-Za-z]+$', text)
    word, left = m[0], text[:m.start()]
    lower = word.lower()
    if lower == 'homework':
        if re.search(r'\b(?:[Mm]ath|[Pp]hysics|[Aa]sk a)\s+$', left):
            return .85
        return -.27 if re.search(r'\bassignment\s+$', left) else .05
    if lower == 'solved':
        if position == 1 and left == '' and word == 'Solved':
            return 8.9
        return .7 if word.istitle() else .12
    if lower == 'expert':
        if re.search(r'\bMath\s+$', left):
            return .8
        return -.15 if word.islower() else -.02
    if lower == 'by':
        if re.search(r'(?:^|\n)#+[^\n]*\n\nposted\s+$', left):
            return 1.7
        if re.search(r'\b(?:Answers|Questions|Asked)\s+$', left):
            return .5
    if word in ('Questions', 'Tutorials', 'Documents') and re.search(
            r'\bRelated\s+$', left):
        return .8
    if word == 'Languages' and re.search(r'\bProgramming\s+$', left):
        return .8
    if lower in ('other', 'questions') and re.search(
            r'\bBrowse(?: other)?\s+$', left):
        return 1.0
    if lower == 'own' and re.search(r'\bask your\s+$', left):
        return 1.5
    if lower in ('question', 'questions') and word.islower():
        return -.09
    if lower in SUBJECTS:
        title = word.istitle()
        heading = not left.rsplit('\n', 1)[-1].strip(' #\t')
        label = bool(re.search(
            r'\b(?:on|Subject|Subjects|Concentration)[,: ]*$', left))
        compound = bool(re.search(r'(?:[A-Z][a-z]+\s+|[&/,»>]\s*)$', left))
        if re.search(r'Assignment Help[^\n]*$', left):
            return 2.0
        if title and lower == 'mathematics':
            return 1.2 if heading or label or compound else .05
        if title and lower in SCIENCES:
            return .5 if label else .35
        if title and (heading or label or compound):
            return .5 if lower == 'management' else .25
        if lower == 'engineering' and re.search(
                r'\b(?:mechanical|electrical|chemical|civil)\s+$', left):
            return .3
        if word.islower() and lower in ('computer', 'management'):
            return -.18
        if word.islower() and lower in ('mathematics', 'algebra'):
            return -.1
