def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        before, position = '', 0
    else:
        _, before, position = carry
    s = prefix.token_strings[-1]
    value = predict(s, before, position)
    return (doc, (before + s)[-256:], position + 1), value

