Unix root directory names give large responses, particularly when their
leading slash was a separate token.  Windows drive and home paths behave
similarly.  Ordinary slash-separated fragments give smaller responses.
Small negative adjustments cover 'and/or' and test PASS labels.
Only a short text suffix is retained, and it resets at document boundaries.
This deliberately omits token-specific differences between path fragments.
"""
import re

READS = ()

# Familiar root directories, sandboxes, and the /path/to placeholder.
PATH_HEADS = {
    'workspace': 10.8,
    'opt': 11.0,
    'usr': 6.3,
    'root': 6.3,
    'tmp': 5.0,
    'home': 11.5,
    'Users': 16.0,
    'media': 9.8,
    'etc': 3.1,
    'dev': 1.2,
    'path': 3.5,
}
SOURCE_DIRECTORIES = {'src', 'lib', 'java', 'build', 'tools'}
PACKAGE_DOMAINS = {'com', 'org', 'net', 'io', 'cn', 'br'}


def response(token, previous, tail):
    stripped = token.lstrip()
    if '://' in token:
        return 2.0
    if token in PATH_HEADS and tail.endswith('/'):
        return PATH_HEADS[token]

    # Windows home directories and drive-letter paths.
    if token == 'Users' and tail.endswith('\\'):
        return 11.7
    if token == ':\\' and re.search(r'\b[A-Z]$', tail):
        return 14.0
    if token == '\\Desktop':
        return 10.0

    # Placeholder paths and standard system-installation prefixes.
    if token == '/to' and tail.endswith('path'):
        return 7.0
    if token == '/local' and tail.endswith('/usr'):
        return 11.1
    if token in ('/lib', '/share') and re.search(r'/usr(?:/local)?$', tail):
        return 6.4
    if token == '/site' and tail.endswith('/lib'):
        return 3.5

    if re.fullmatch(r'''[ \t]*[`'"(]+/''', token):
        return 1.2
    if stripped == './':
        return 1.1
    if token == '/or' and tail.endswith('and'):
        return -0.3
    if stripped.startswith('/') and not stripped.startswith('//'):
        if stripped == '/':
            if previous in PATH_HEADS or tail.endswith('/testbed'):
                return 3.4
            if previous in ('.git', '.github'):
                return 2.3
            if token.startswith(' '):
                if tail.endswith('directory:'):
                    return 3.2
                if tail.endswith('cd'):
                    return 2.1
                return 1.2
            return 0.6
        if re.fullmatch(r'/[A-Za-z.]+', stripped):
            part = stripped[1:]
            if part == 'workspace':
                return 4.5
            if part == 'usr':
                return 5.8
            if part == 'opt':
                return 3.0
            if part == '.':
                return 2.5
            if part in PACKAGE_DOMAINS:
                return 1.8
            value = 0.85 if len(part) <= 2 else 0.25
            if part in SOURCE_DIRECTORIES:
                value = 1.2
            if part == 'test':
                value = 0.85
            if re.search(r'/(?:workspace|testbed|tmp|root|Users|home)$', tail):
                if len(part) <= 2:
                    value += 2.0
                elif part in SOURCE_DIRECTORIES:
                    value += 1.2
            return value

    # Package-name roots, hidden project directories, and test output.
    if stripped in PACKAGE_DOMAINS and token.startswith(' '):
        if re.search(r'\b(?:import|package|link)\s*$', tail):
            return 3.0 if stripped == 'com' else 1.8
    if token == '.com' and re.search(r'\b(?:import|package) br$', tail):
        return 3.2
    if token == '.github':
        return 1.9
    if token == ' PASS':
        return -0.5
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, tail = '', ''
    else:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (document, token, (tail + token)[-96:]), value

