"""Filesystem-path detector: fires on the directory names and path separators of Unix and
Windows file paths and URLs, most strongly on the top-level sandbox/system directories
(/workspace, /opt, /local, /usr, /tmp, /home, /Users, C:\\Users, ...).

Each token is scored on its own spelling and on the token before it:
- a root-directory name right after a slash (the first folder of an absolute path)
  is strong: "/workspace" as "/" + "workspace" fires about 11, the merged token "/workspace" about 5;
- a path separator "/" after a folder name is moderate (about 1, more after known
  project or system folders such as opt/, workspace/, node_modules/), and about 0 after a
  digit, where "/" is a fraction or a date;
- "://" and the domain pieces of a URL (".org", ".com") are weak to moderate.
Everything else (prose, code, numbers) predicts 0.
"""

READS = ()

# a directory name right after a path separator ("/", " /", or "\" as in C:\Users)
DIR_NAMES = {
    "workspace": 11.0, "local": 11.0, "opt": 9.0, "home": 10.0, "usr": 6.0, "tmp": 5.0,
    "Users": 10.0, "Volumes": 12.0, "Applications": 12.0, "Desktop": 8.0,
    "root": 4.0, "etc": 3.0, "lib": 3.0,
}
# the same names with their slash merged into one token
MERGED = {
    "/workspace": 4.7, "/local": 11.0, "/opt": 8.0, "/usr": 6.0, "/tmp": 5.0,
    "/root": 3.5, "/Users": 5.0, "/etc": 3.0, "/lib": 3.0, "/home": 4.0, "/share": 6.0,
}
# a slash after a folder name that is itself a known root or project folder
PARENT_DIRS = {
    "workspace": 3.0, "bed": 3.0, "opt": 5.0, "node_modules": 3.7, "tmp": 3.6,
    "Volumes": 8.0, "tests": 2.7, ".github": 2.3, "src": 1.6,
}
DOMAIN_PARTS = {" org": 1.8, " com": 0.8, ".com": 0.4, " net": 0.5}
DIGITS = set("0123456789")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]  # the token being predicted
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if s in MERGED:
        return None, MERGED[s]
    if s in DIR_NAMES and prev.endswith(("/", "\\")):
        return None, DIR_NAMES[s]
    if s == "://":
        return None, 1.9
    if s in DOMAIN_PARTS:
        return None, DOMAIN_PARTS[s]
    if s in ("/", " /"):
        if prev[-1:] in DIGITS:  # division or a date, not a path
            return None, 0.0
        return None, PARENT_DIRS.get(prev.strip(), 1.0)
