from wordfreq import zipf_frequency

READS = ()
_FOREIGN = regex.compile(r'[\p{Script=Greek}\p{Script=Cyrillic}]')
_LETTERS = regex.compile(r'\p{L}+$')
_GREEK = regex.compile(r'\p{Script=Greek}')


@lru_cache(maxsize=8192)
def spelling(text):
    if _FOREIGN.search(text):
        text = anyascii(text)
    return ''.join(c for c in unicodedata.normalize('NFKD', text.lower())
                   if not unicodedata.combining(c))


@lru_cache(maxsize=4096)
def word_formation_strength(base, suffix):
    # A normal English suffix on a familiar noun is not a new dic stem.
    if (len(base) >= 4 and zipf_frequency(base, 'en') >= 4.2
            and 'noun' in wordnet.parts_of_speech(base)):
        return 0.0
    formed = base + suffix
    parts = wordnet.parts_of_speech(formed)
    if suffix.startswith('ix') and 'noun' in parts:
        if zipf_frequency(formed, 'en') >= 3.5:
            return 0.0
    return 0.5 if 'adjective' in parts else 1.0


def response(raw_token, raw_previous):
    if raw_token[:1].isspace():
        raw_previous = ''
    greek = bool(_GREEK.search(raw_previous + raw_token))
    s = spelling(raw_token).lstrip().lstrip('_')
    p = spelling(raw_previous)
    last = p[-1:]
    # More distant d context is weaker than the immediate d + ic contrast.
    distance = len(p) - p.rfind('d') if 'd' in p else 100
    if s in ('ic', 'ik', 'iq') and 2 <= distance <= 4:
        return -1.4 * 0.7 ** (distance - 2)
    if last == 'd':
        if re.fullmatch(r'[eou]x', s):
            return -1.2
        if s == 'ich' or s.startswith('iche'):
            return -2.2
        if s == 'yc':
            return -3.2
    if p.endswith('du') and s.startswith('c') and len(s) <= 3:
        return -1.1
    if re.match(r'i[ckqx]', s) and not s.startswith('ich'):
        if last == 'd':
            value = -5.8 if len(s) == 2 else -3.0
            if s.startswith('ix'):
                value = -3.5
            return value * word_formation_strength(p, s)
        if len(s) == 2:
            if last in ('g', 'k'):
                return 2.0
            if last in ('b', 'h'):
                return 1.0
            if last in ('n', 'p', 'm', 'l', 'f', 'u', 'c'):
                return 0.4
            if last in ('s', 'z'):
                return -0.4
            return 0.0
        return 0.7 if last == 'g' else 0.05
    if 'dedic' in s or s == 'edic':
        return -3.2
    if re.fullmatch(r'(?:in|pre)?dic', s):
        return -3.0
    if s.startswith(('dic', 'indic')) or s.endswith('dict'):
        return -0.4
    if p.endswith('di') and re.match(r'[ckqx]', s):
        return -3.5
    if greek and p.endswith('k') and s in ('a', 'e', 'i', 'o', 'u'):
        return 1.2
    if re.search(r'di[ckqx]$', p) and s[:1].isalpha():
        return -1.4 if s.startswith('a') else -0.2
    if p.endswith('i') and re.match(r'[ckqx]', s):
        return 2.2 if greek and len(s) == 1 else 0.1
    return 0.0


def advance(previous, token):
    match = _LETTERS.search((previous + token.replace('\x00', ''))[-64:])
    return match.group()[-32:] if match else ''


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, previous)
    return (doc, advance(previous, token)), value

"""A small lexical approximation, not a general semantic parser.

The clearest recurring negative responses are Chinese passive/adverse markers
and emphatic or quoted endings. Space-prefixed unfinished Han characters
have a small negative baseline. Openings use a positive word-shape prior.
A few English temporal/status expressions and grammatical particles have
relatively stable signs. Additional negative responses mark selected event
continuations: future "set to", aftermath "after", and event-related "in".
A short history supplies a technical-setting veto and a lost-interest cue.
Unrecognized tokens are left near zero.
"""
import regex

READS = ()

# Distinguish prose about an impending event ("set to return") from
# technical assignments ("set to true", "value is set to ...").
TECHNICAL = regex.compile(
    r"\b(?:value|variable|parameter|label|flag|default|true|false|"
    r"algorithm|rate|data|bits?\d*|array|field|option|temperature|oven|"
    r"resample|rule|capitaliz\w*|mean|deviation)\b|[={}_`\\]|"
    r"\p{Script=Greek}|&#\d|\b[a-z]\s+\d\b"
)
CJK = regex.compile(r"[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    word = text.strip()
    beginning = carry is None or carry[0] != doc or previous == '<|endoftext|>'
    history = '' if beginning else carry[2]
    state = (doc, text, (history + text.lower())[-180:])
    if beginning:
        if len(word) <= 1:
            value = 0.08 if word.isascii() else 0.27
        elif word in {'a', 'an', 'the'}:
            value = 0.0
        elif word.istitle():
            value = 0.30 if len(word) > 3 else 0.23
        else:
            value = 0.22 if text.startswith(' ') else 0.16
        return state, value

    value = 0.0
    raw = prefix.token_bytes[-1]
    unspaced = raw.lstrip(b' ')
    if (raw.startswith(b' ') and unspaced and
            0xE4 <= unspaced[0] <= 0xE9 and '\ufffd' in text):
        value -= 0.08
    if word == '！':
        value -= 0.43
    elif word == '!' and CJK.search(history[-20:]):
        value -= 0.11
    if any(c in text for c in '」』'):
        value -= 0.23
    if word in {'被', '遭'}:
        value -= 0.43
    if word in {'新', '新型'}:
        value -= 0.22
    if text == 'の':
        value += 0.08
    if text == '了':
        value += 0.08

    if text.startswith(' '):
        lower = word.lower()
        if lower == 'today':
            value += 0.25
        if lower == 'after':
            value -= 0.11
            p = previous.strip().lower()
            if not TECHNICAL.search(history) and (
                (p.endswith('ed') and p not in {
                    'named', 'patterned', 'modeled', 'modelled', 'fashioned'
                }) or p in {'died', 'dies', 'dead', 'death', 'down'}
            ):
                value -= 0.20
        if lower in {'ahead', 'underway'}:
            value -= 0.23
        if lower in {'without', 'against', 'between', 'along', 'despite'}:
            value -= 0.05
        if lower == 'be':
            value += 0.03
        p = previous.strip().lower()
        if lower == 'to' and p == 'set' and not TECHNICAL.search(history):
            value -= 0.70
        if lower == 'in' and p in {
            'compete', 'competing', 'collide', 'collided',
        } and not TECHNICAL.search(history):
            value -= 0.30
        if lower == 'in' and regex.search(
            r'\b(?:lose|loses|lost|losing) interest$', history
        ):
            value -= 0.60
    return state, value

"""Approximate a negative response to lowercase text at sentence boundaries.

Full stops after long words give a larger response than one- or two-letter
words and numeral list markers. Single Latin letters and code-like contexts weaken it.
There is a smaller line/paragraph-onset response, a short subword after-effect,
and a few distinctive numeral and document-initial punctuation responses.
The program uses text and resets its context at each document boundary.
"""
import re

READS = ()
LAST_WORD = re.compile(r'([^\W_]+)$', re.UNICODE)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0., 0, None)
    _, tail, fading, depth, uniform = carry
    token = prefix.token_strings[-1]
    s = token.lstrip()
    clean = tail.rstrip()
    gap = tail[len(clean):]
    spaced = bool(gap) or s != token
    code = any(ch in tail[-100:] for ch in '{};=<>_')
    value = 0.
    onset = False
    if s[:1].islower():
        single = s.isascii() and len(s) == 1
        if clean.endswith('.') and not clean.endswith('..') and spaced:
            match = LAST_WORD.search(clean[:-1])
            word = match[0] if match else ''
            if word.isdigit():
                value = -0.8
            elif len(word) <= 2:
                value = -0.3
            else:
                if single:
                    value = -0.6 if token == s else -0.3
                else:
                    value = -1.4
            if word.isupper() and len(word) > 1:
                value = -1.1
            if code:
                value *= 0.45
            onset = True
        elif clean.endswith(('!', '?')) and spaced:
            value = -0.3 if single else -0.65
            if code:
                value *= 0.25
            onset = True
        elif '\n' in gap:
            if code:
                value = -0.02
            else:
                value = -0.43 if '\n\n' in gap else -0.14
            if '<|im_start|>' in tail and clean.endswith(
                    ('user', 'assistant', 'system')):
                value = -1.0
            onset = True
        elif tail.endswith('\\n'):
            value = -0.18
            onset = True
        elif token.startswith(' ') and gap == ' ' and not code:
            value = -0.14
        elif clean.endswith('|') and token.startswith(' ') and not code:
            value = -0.09

        if '\n' in gap:
            line = clean.rsplit('\n', 1)[-1]
            if line.isupper() and sum(ch.isupper() for ch in line) >= 5:
                value, onset = -1.6, True

    if onset:
        fading, depth = value * 0.25, 0
    elif fading and token[:1].islower() and tail[-1:].isalpha():
        value = fading if depth == 0 else fading * 0.25
        depth += 1
    else:
        fading, depth = 0., 0

    # Exceptional numeral prefix at the beginning, observed also in probes.
    if tail == '1' and token == '2':
        value = -6.139
    elif tail == '12' and token == '2':
        value = -2.585

    # A homogeneous punctuation prefix retains its initial response.
    uniform = token if not tail else uniform if token == uniform else None
    if uniform == '··':
        value = -4.143
    elif uniform == '^^^^':
        value = -3.13
    elif uniform == '\r':
        value = -3.54
    return (doc, (tail + token)[-128:], fading, depth, uniform), value

"""A document-onset signal whose sign depends on token typography.

It stays on for repetitions of the initial token, then switches off. Bare
lowercase Latin tokens and digits are positive; capitalized words are
negative. Single letters, word-boundary spaces, and whitespace runs differ.
Middle-dot separators and opening quotes are negative. Words are pooled
into classes rather than memorized individually.
"""
import unicodedata

READS = ()


def onset_value(text):
    if text == '<|im_start|>':
        return -5.9
    if text.startswith('<|'):
        return 0.0
    if text.isspace():
        if '\n' in text:
            return 5.7 if text == '\n' else 1.3
        return 5.2 if text == ' ' else 8.0
    word = text.strip()
    if word and all(ch == '·' for ch in word):
        return -10.2
    if word.isdecimal():
        return 7.5
    if word.isascii() and word.isalpha():
        n = len(word)
        if word.islower():
            if text[0].isspace():
                return 6.0 if n == 1 else max(-3.8, -0.9 - 0.45*(n-2))
            return 17.2 if n == 1 else 9.5 if n <= 4 else 7.8
        return -1.8 if n == 1 else -6.5
    if word.isalpha() and word.islower():
        return -2.0 if text[0].isspace() else 4.0
    if word and word[0].isupper():
        return -5.5
    if word.isalpha():
        return -3.6
    if '\ufffd' in word:
        return -2.7
    if text[:1].isspace():
        return -1.2
    if word and unicodedata.category(word[0]) == 'Pi':
        return -9.0
    return 0.5


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_ids[-1]
    if carry is None or doc != carry[0]:
        value = onset_value(prefix.token_strings[-1])
    else:
        value = carry[2] if token == carry[1] else 0.0
    return (doc, token, value), value

programs.haiku:
"""layers.1.mlp.down_proj:2471 -- a component that reacts to the first token of a document.

What it does, in plain terms:
  * At the first token of each document (the first token of a row, or the first token after
    a document boundary, where the model resets its attention and positions), it writes a
    value that depends on what that token looks like:
      - a lowercase word fragment with no leading space: strongly positive, more so the
        shorter it is (one letter ~ +17, two letters ~ +11, three or four ~ +9.5, longer ~ +7);
      - a bare space token: +5.9;
      - a digit: +7.6;
      - a lone lowercase letter after a space: +6.5 (longer lowercase words after a space: -1.5);
      - a capitalised word start: -6.5 (a lone capital: -1.5);
      - a special chat token such as <|im_start|>: -5.9;
      - a non-ASCII letter: -2.5; other ASCII punctuation: about 0.
  * On the token "··" it writes -10.2 wherever it occurs.
  * Everywhere else it writes 0.

Why: the component's activation is large only at document starts and on the "··" token; over
the rest of the text it is small noise. Its effect on the model is therefore concentrated at
the start of each document.

Main program: `step` below reads the newest token and whether it begins a document.
"""

READS = ()

FIRST_TOKEN_VALUE = {1: 17.0, 2: 11.0}  # by length, for lowercase fragments with no leading space


def is_document_start(prefix):
    """True at a row's first token and at the first token after a document boundary."""
    return len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]


def first_token_value(s):
    """The component's value at a document's first token, from the token's string."""
    if s.startswith("<|"):
        return -5.9  # special chat token
    spaced = s[:1] == " "
    word = s.lstrip(" ")
    n = len(word.rstrip())
    c = word[:1]
    if c == "":
        return 5.9  # a bare space token
    if c.isascii() and c.islower():
        if spaced:
            return 6.5 if n == 1 else -1.5
        return FIRST_TOKEN_VALUE.get(n, 9.5 if n <= 4 else 7.2)
    if c.isdigit():
        return 7.6
    if c.isascii() and c.isupper():
        return -1.5 if n == 1 else -6.5
    if c.isascii():
        return 0.0  # ASCII punctuation
    return -2.5  # non-ASCII letters and symbols


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if s == "··":
        return carry, -10.2
    if not is_document_start(prefix):
        return carry, 0.0
    return carry, first_token_value(s)

