"""Opening markers and source-code dependency declarations.

At document starts, recognize code/comment preambles, markup, and selected
opening words. Use smaller script/case, whitespace, and digit baselines.
Later, predict positive dependency-keyword responses at line starts,
especially after semicolon-terminated lines. Handle two opening sequences:
'Title:' has a negative colon; a second '//' header line is positive.
Other positions get zero. This omits the small token-dependent background.
"""
import regex as re

READS = ()

# These are literal source-language preambles, not arbitrary vocabulary IDs.
CODE_PREAMBLES = {
    'package': 10.86,
    'from': 3.6,
    '#if': 3.8,
    '#ifndef': 3.5,
    '#ifdef': 1.0,
}
QUESTION_OPENERS = {
    'How': 6.4,
    'how': 3.6,
    ' how': 2.1,
    'Why': 3.6,
    'When': 1.8,
}
METADATA_LABELS = {'Title': 2.4, 'Question': 1.9, 'Description': 1.3}


def opening(token):
    for group in (CODE_PREAMBLES, QUESTION_OPENERS, METADATA_LABELS):
        if token in group:
            return group[token]
    if re.fullmatch(r'#{1,3}', token):
        return 4.7 if len(token) < 3 else 3.9
    if token.startswith('/*') and len(token) < 8:
        value = 3.8 if token.startswith('/**') else 6.7
        return value - (0.8 if '\r\n' in token else 0.0)
    if token.rstrip() == '//':
        return (0.5 if '\r' in token else -0.5) if '\n' in token else 3.1
    if token.rstrip() in ('"""', "'''"):
        return 5.2 if '\n' in token else 3.9
    if token == 'I':
        return 5.5
    if token == ' I':
        return 2.3
    if token == '"I':
        return 4.3
    if token in ('My', 'my'):
        return 2.2
    if token in ('%', ' %'):
        return 4.1 if token == '%' else 2.3
    if token == '**':
        return 4.2
    if token == '--':
        return 3.6
    if token == '【':
        return 2.1
    if token == "'":
        return 2.6
    if re.fullmatch(r'\p{Script=Cyrillic}+', token.strip()):
        return 1.7 if token.strip().isupper() else 0.35
    if token.isspace():
        return 0.25
    if token.isdigit():
        return 0.2
    return 0.05


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        return (doc, token[-96:], token, 1), opening(token)
    _, tail, first, position = carry
    value = 0.0
    # Also recognize newlines in source code embedded in escaped strings.
    left = tail.replace('\\n', '\n').replace('\\r', '\r')
    at_line_start = bool(re.search(r'\n[ \t]*$', left))
    word = token.strip()
    if position == 1 and first == 'Title' and token == ':':
        value = -4.0
    elif position == 1 and first == '//\n' and token == '//':
        value = 4.0
    elif word in ('import', 'using', 'use', 'namespace'):
        if at_line_start:
            after_semicolon = left.rstrip().endswith(';')
            blank = bool(re.search(r'\n[ \t]*\n[ \t]*$', left))
            if after_semicolon:
                value = 1.5 + (0.3 if blank else 0.0)
            elif word == 'namespace':
                value = 0.5
            elif word == 'using':
                value = 0.2
            elif word == 'use':
                value = 0.4
            else:
                value = 0.1 if blank else 0.0
        elif token.startswith('\t'):
            value = 0.25 if word == 'import' else 0.6
        elif token == ' import':
            value = -0.11
    elif word == 'from':
        if at_line_start:
            value = 0.95 if token == 'from' else 0.75
        elif token.startswith('\t'):
            value = 0.68
    return (doc, (tail + token)[-96:], first, position + 1), value

