"""layers.1.mlp.down_proj:2472 - fires at document openers and at import statements.

Positive activation in three situations, zero elsewhere:
1. The first token of a document (the position after <|endoftext|>, where attention
   sees nothing else). A comment or heading opener (#, ##, /*, //, %, --, a docstring
   quote) gives about 4; the sentence openers I, How, Who, Why, My, Other, One, User
   give about 4; and a file-header keyword gives its own value: package 10,
   namespace 3, from 3.6.
2. Inside a Java/C#/Kotlin-style file (one whose earlier lines end in ';'), a
   line-leading `import` or `using` (the keyword before a dotted package path such
   as java.util.List) gives about 1.2.
3. In any file, a line-leading `from` (a Python import statement) gives about 0.6.
"""

READS = ()

OPENERS = {"#", "##", "###", "/*", "//", "%", "**", "--", '"""', "'''", "<!--"}
SENTENCE = {"I", "How", "Who", "Why", "My", "Other", "Another", "One", "User"}
HEADER = {"package": 10.0, "namespace": 3.0, "from": 3.6}
JAVA_IMPORT = {"import", "using"}
PY_IMPORT = {"from", "\tfrom"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc_start = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    # carry: whether an earlier line of this document ended in ';' (Java/C#-style)
    semi_seen = False if (carry is None or doc_start) else carry
    if doc_start:
        tok = raw.strip()
        if raw in HEADER:
            value = HEADER[raw]
        elif tok in OPENERS or tok in SENTENCE:
            value = 4.0
        else:
            value = 0.0
    elif semi_seen and raw in JAVA_IMPORT:
        value = 1.2
    elif raw in PY_IMPORT:
        value = 0.6
    else:
        value = 0.0
    return semi_seen or ";" in raw, value

