"""A sparse recognizer for interface phrases and source-code library names.

Forum/navigation labels give positive pulses; qualified library and header
names generally give negative pulses. The constants approximate observed
pulse sizes, not an exact reconstruction. Other text stays near zero.
Only a short suffix is remembered, resetting at each document boundary.
"""
import re

READS = ()

# Familiar standard-library and platform namespaces.
JAVA = {
    'math': -6.5, 'net': -3.7, 'io': -2.06, 'nio': -2.31,
    'text': -1.32, 'security': -3.73, 'time': -2.56,
    'sql': -1.47, 'awt': -1.11, 'util': -0.91,
}
ANDROID = {
    'graphics': -5.74, 'net': -2.88, 'os': -2.4,
    'app': -2.0, 'content': -0.87,
}
SYSTEM = {'net': -2.51, 'threading': -0.85, 'data': -0.68, 'linq': -0.32}
HEADERS = {
    'math': -4.02, 'cmath': -3.22, 'sys': -6.25, 'string': -1.94,
    'time': -1.98, 'unistd': -0.65, 'openssl': -1.2, 'arpa': -2.49,
}
PYTHON = {'math': -2.51, 'string': -0.96, 'matplotlib': -0.69, 'numpy': -0.35}

# Short collocations common in discussion forums and document navigation.
PHRASES = {
    ('latest', 'reply'): 24.06,
    ('latest', 'member'): 2.4,
    ('latest', 'news'): 0.85,
    ('latest', 'posts'): 2.67,
    ('latest', 'in'): 0.49,
    ('last', 'seen'): 1.33,
    ('last', 'visit'): 0.9,
    ('last', 'visited'): 3.83,
    ('last', 'post'): 1.84,
    ('first', 'post'): 0.12,
    ('display', 'posts'): 0.98,
    ('recommended', 'posts'): 4.2,
    ('other', 'sites'): 0.69,
    ('view', 'profile'): 0.87,
    ('full', 'document'): 0.58,
    ('full', 'post'): 3.15,
    ('expert', 'tutors'): 0.8,
    ('expert', 'replies'): 3.5,
    ('member', 'reply'): 2.4,
    ('post', 'reply'): 3.76,
    ('post', 'replies'): 3.56,
    ('the', 'likes'): 1.54,
    ('no', 'reviews'): 1.84,
}


def activation(tail, token):
    word = token.strip().lower()
    before = tail.lower()
    words = re.findall(r'[a-z]+', before[-50:])
    prev = words[-1] if words else ''
    line = before.rsplit('\n', 1)[-1]
    segment = word.lstrip('./')

    for name, table in (('java', JAVA), ('android', ANDROID),
                        ('system', SYSTEM)):
        if before.endswith(name) and token.startswith('.'):
            if segment in table:
                return table[segment]
    if before.endswith('java.lang') and word == '.reflect':
        return -4.58
    if before.endswith('java.util') and word == '.stream':
        return -1.32
    if re.search(r'#\s*include\s*[<"][^>"\n]*$', line):
        if segment in HEADERS:
            return HEADERS[segment]
        if before.endswith('sys'):
            if word == '/types':
                return -5.68
            if word == '/socket':
                return -2.95
    if re.search(r'\bimport\s*$', line) and word in PYTHON:
        return PYTHON[word]
    if word == 'pd' and re.search(r'pandas\s+as\s*$', before):
        return 1.13
    if word == 'np' and re.search(r'numpy\s+as\s*$', before):
        return 0.7
    if token == '/wiki' and 'wikipedia' in before[-80:]:
        return -1.52

    if word == 'post' and re.search(r'my\s+first\s*$', before):
        return 0.7
    if (prev, word) in PHRASES:
        return PHRASES[prev, word]
    if word == 'replies' and re.search(r'\d\s*$', before):
        return 1.75
    if word == 'post' and before.endswith('layout:'):
        return 1.38
    if word == 'showing' and prev == 'cancel':
        return 14.39
    if token == ':\n' and before == 'question':
        return 5.08
    if word == 'editions' and re.search(r'view\s+more\s*$', before):
        return 4.19
    if len(token) >= 2 and set(token) == {'·'}:
        return 0.43
    return -0.0007


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    last_doc, tail = carry if carry is not None else (None, '')
    if doc != last_doc:
        tail = ''
    token = prefix.token_strings[-1]
    value = activation(tail, token)
    return (doc, (tail + token)[-160:]), float(value)

