"""layers.1.mlp.down_proj:2473, a "platform library name in an import" detector.

What it does: it reads the name of the library that a code line imports or includes, and
answers negative when that library is a platform or system library. Java and Android
packages (import java.net..., import android.os...) and C/POSIX system headers
(#include <sys/types.h>, <math.h>, <string.h>) push the activation down, the more
low-level the library the further down: java.math / java.net / sys / math are strongest,
java.io / java.nio / string / time are medium, java.util / algorithm / unistd are weak.
Standard I/O headers (stdio, stdlib, iostream) and other names stay near 0. Java package
declarations ("package ...") are slightly negative too. Everywhere else the program predicts 0.

What it does not capture: the activation is mostly small and diffuse; this program explains
only the large, legible negative events in import and include lines. The positive side (forum
boilerplate, miscellaneous words) is left out, because adding it lowered the score.
"""
READS = ()

# Name right after "import java." or "import android.": platform packages, strongest first.
STRONG_PACKAGES = {"graphics", "net", "security"}
MEDIUM_PACKAGES = {"nio", "os", "io", "time", "text", "lang", "app", "sql", "database"}
WEAK_PACKAGES = {"content", "support", "awt", "util"}

# Name right after "#include <": system and POSIX headers, strongest first.
STRONG_HEADERS = {"sys", "net", "math"}
MEDIUM_HEADERS = {"fcntl", "cmath", "asm", "limits", "arpa", "linux", "string", "time", "netinet"}
WEAK_HEADERS = {"algorithm", "signal", "unistd", "vector", "bits"}


def _tier(name, strong, medium, weak, default):
    """Activation for a library name: -5 strong, -2 medium, -1 weak, else `default`."""
    if name in strong:
        return -5.0
    if name in medium:
        return -2.0
    if name in weak:
        return -1.0
    return default


def _line_before(prefix):
    """Text of the current line before the newest token, within the same document."""
    toks = prefix.token_strings
    doc = prefix.document_ids[-1]
    out = []
    for i in range(len(toks) - 2, max(-1, len(toks) - 40), -1):
        if prefix.document_ids[i] != doc or "\n" in toks[i]:
            break
        out.append(toks[i])
    return "".join(reversed(out)).lstrip()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1].strip(" .<>\"/")
    prev = toks[-2].strip() if len(toks) > 1 else ""
    line = _line_before(prefix)
    if prev in ("java", "android") and line.startswith("import"):
        return carry, _tier(cur, STRONG_PACKAGES, MEDIUM_PACKAGES, WEAK_PACKAGES, -0.3)
    if prev == "<" and line.startswith("#include"):
        return carry, _tier(cur, STRONG_HEADERS, MEDIUM_HEADERS, WEAK_HEADERS, 0.0)
    if prev == "sys" and line.startswith("#include"):
        return carry, -5.0  # sys/types.h, sys/socket.h, ...: the path under a system header
    if line == "" and cur == "package":
        return carry, -0.4  # Java package declaration
    return carry, 0.0

programs.sol:
"""Recognize plural quantities, especially Chinese 'these/those/some/many'.

Chinese quantifiers give the largest response; fusing them with extra
characters in one token usually weakens it. Short context also recognizes
split collection classifiers ('one/this/that group, heap, batch').
In English the response is mostly delayed to 'of': 'some of', 'a lot of',
and indefinite 'a number/series of', rather than 'the number of'.
'All of' and French 'tous/toutes les' instead receive negative values.
Several other languages' quantity markers have smaller fixed responses.
Keep only 100 characters of history, resetting at each document boundary.
These rules capture the quantity pattern, not all small lexical fluctuations.
"""
import re
from functools import lru_cache
from opencc import OpenCC

READS = ()
_SIMPLIFY = OpenCC('t2s')

# Different kinds of Chinese plural/quantity expressions.
CHINESE = (
    (r'[这那]些', 6.7),
    (r'哪些', 4.5),
    (r'一些|有些|许多|很多|不少|众多|诸多', 4.1),
    (r'好多|无数|[这那]么多', 3.2),
    (r'某些|更多', 2.1),
    (r'太多|多人', 2.5),
    (r'所有', 2.05),
    (r'大量', 1.8),
    (r'大多数|越来越多|多少|少数|种种|一切', 1.2),
    (r'大部分|一部分|多数|大多|过多|越多|不多|多多|无限', 0.9),
    (r'其他|其它|其余|都是|大家都|部分', 0.65),
    (r'[一这那]群人?|[一这那]批|一系列|一大堆', 2.8),
)
_PATTERNS = [(re.compile(pattern), value) for pattern, value in CHINESE]

@lru_cache(maxsize=16384)
def chinese_value(token):
    s = _SIMPLIFY.convert(token.strip())
    if s in ('版权所有', '作者所有', '不少于'):
        return 0.0
    for pattern, value in _PATTERNS:
        m = pattern.search(s)
        if m:
            before, after = s[:m.start()], s[m.end():]
            if before == '的':
                value *= 0.55
            elif before and before not in ('把',):
                value *= 0.9 if before in ('有', '了') else 0.7 ** len(before)
            return value * 0.7 ** len(after)
    if s == '些':
        return 5.0
    if s in ('皆', '色々', '多くの'):
        return 1.1
    if s == 'これらの':
        return 1.4
    if s == 'いろいろ':
        return 0.65
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = chinese_value(token)
    if word == 'of':
        previous = re.findall(r"[a-z]+|%", history.lower())
        last = previous[-1] if previous else ''
        if last == 'some':
            value = 2.1
        elif last == 'lot':
            value = 0.9
        elif last == 'bunch':
            modifier = previous[-2] if len(previous) > 1 else ''
            value = 2.0 if modifier in ('a', 'whole') else 0.3
        elif last in ('number', 'numbers', 'series', 'group'):
            modifier = previous[-2] if len(previous) > 1 else ''
            # Bare indefinite counts differ from definite 'the number of'.
            if last == 'series' and modifier in ('a', 'whole'):
                value = 1.3
            elif last in ('number', 'numbers'):
                if modifier in ('a', 'some'):
                    value = 0.95
                elif modifier == 'any':
                    value = 0.65
                elif modifier in ('large', 'great', 'huge'):
                    value = 1.5 if last == 'number' else 1.0
                elif modifier in ('small', 'considerable', 'larger'):
                    value = 0.6
            elif last == 'group' and modifier == 'large':
                value = 0.65
        elif last == 'all':
            value = -0.45
        elif last == 'many':
            value = -0.2
        elif last in ('most', 'none', 'both', 'few', 'several', 'each',
                      'any', 'much', 'percent', '%', 'thousands', 'millions'):
            value = 0.25
    elif word == 'bunch':
        value = 1.0 if re.search(r'\b(?:a|whole)\s*$', history.lower()) else 0.1
    elif word in ('these', 'those'):
        value = 0.75 if re.search(r'\ball\s*$', history.lower()) else -0.1
    elif word == 'many' and re.search(r'\b(?:good|great)\s*$', history.lower()):
        value = 1.3
    elif word in ('nhiều', 'nhiêu', 'banyak'):
        value = 1.0
    elif word in ('những', 'ững'):
        value = 0.7
    elif word == 'les' and re.search(r'\b(?:tous|toutes)\s*$', history):
        value = -2.0
    # A separately tokenized Chinese 'many' needs its preceding intensifier.
    if token == '多' and re.search(
            r'[很许众诸挺甚良颇较蛮够]$', _SIMPLIFY.convert(history[-2:])):
        value = 2.8
    # Collection classifiers can be split from 'one/this/that' by tokenization.
    chinese = (_SIMPLIFY.convert(token)
               if len(token) == 1 and not token.isascii() else '')
    if chinese and chinese in '群堆帮批团众串半数':
        tail = _SIMPLIFY.convert(history[-4:])
        if (chinese in '群堆帮批团众串'
                and re.search(r'[一这那](?:大|连)?$', tail)):
            value = 4.8 if tail.endswith('一大') else 3.2
        elif chinese == '半' and tail.endswith('一'):
            value = 3.2
        elif chinese == '数' and tail.endswith(('无', '多')):
            value = 2.7
    if (token in ('这些', '這些', '那些')
            and history.endswith(('所有', '无论', '無論'))):
        value *= 0.55
    return (doc, (history + token)[-100:]), float(value)

"""Predict boundaries in date stamps, citations, and web/forum metadata.

Spaces before a date's year and semicolons after publication dates are the
main positive cases. Dates standing alone receive more weight than dates in
prose. A few explicit header/navigation rules and document-start offsets
capture other conspicuous cases; ordinary text receives almost zero.
"""
import re
from calendar import month_name, month_abbr, day_name, day_abbr

READS = ()
_MONTHS = set(month_name[1:]) | set(month_abbr[1:])
_M = '(?:' + '|'.join(sorted(_MONTHS, key=len, reverse=True)) + r')\.?'
_D = '(?:' + '|'.join(day_name) + '|' + '|'.join(day_abbr) + ')'
_DAY = re.compile(r'\b' + _D + r',?$', re.I)
_MONTH_DAY = re.compile(r'\b' + _M + r'\s+\d{1,2}(st|nd|rd|th)?(,?)$', re.I)
_FULL_DATE = re.compile(
    r'\b(?:' + _M + r'\s+\d{1,2}(?:st|nd|rd|th)?,?\s+|'
    r'\d{1,2}\s+' + _M + r'\s+)(?:19|20)\d{2}$', re.I)
_YEAR = re.compile(r'(?<!\d)(1[6-9]\d{2}|20\d{2})[a-z]?$')
_JOURNAL_DATE = re.compile(
    r'\b(?:19|20)\d{2}\s+(?:' + '|'.join(_MONTHS) + r')(\.?)(?:\s+\d{1,2})?$', re.I)
_STAMP_LABEL = re.compile(
    r'(?:Posted|Published|Updated|Commented|Last updated|Last edited)'
    r'(?:\s+(?:on|at))?:?$', re.I)


def activation(text, token, position):
    if token == '\r' and not text.strip('\r'):
        return 2.91
    if position == 0 and token == '//\n':
        return 4.73
    if position == 0:
        return -5.47 if token == '<|endoftext|>' else -0.11
    if token == ':' and position == 1 and text == 'Title':
        return -5.72
    if token == ' Posted' and text.endswith('Originally'):
        return -3.06
    if token == '的位置' and re.search(r'[您你](?:现在|当前)$', text):
        return 8.2
    if token == '：' and re.search(r'[您你](?:现在|当前)的位置$', text):
        return 8.2

    if token in (':', ' '):
        label = re.search(r'\b(Joined|Posts|Posted)(:| on)?$', text)
        if label:
            if token == ':':
                return {'Joined': 3.0, 'Posts': 2.16, 'Posted': 0.58}[label[1]]
            if text.endswith('Posted on'):
                return 3.0
            return {'Joined': 0.17, 'Posts': 0.47, 'Posted': 0.2}[label[1]]

    # A weekday followed by the month is a typical date-heading opening.
    if token.strip() in _MONTHS:
        if _DAY.search(text.rstrip(' ,')):
            return 0.9
        if re.search(r'(?:Posted|Published) on$', text):
            return 1.2
    if token not in (' ', ',', ';', ' ;', ' at', ' @', ' by', '\n', '\n\n'):
        return 0.0
    journal = _JOURNAL_DATE.search(text) if token == ';' else None
    if journal:
        return 1.6 if journal[1] else 6.7

    date = _FULL_DATE.search(text)
    year = _YEAR.search(text)
    if year:
        if token == ' ;':
            return 0.5
        if token == ';':
            if int(year[1]) < 1900:
                return 0.65
            return 3.0 if re.search(r'\.\s*$', text[:year.start()]) else 1.7
        if token in (' at', ' @', ' by'):
            if token == ' by' and 'copyright' in text[-50:].lower():
                return 4.5
            prose = re.search(r'\b(?:born|died)\b', text[-100:], re.I)
            if not date or prose or (token == ' by' and date[0][0].isdigit()):
                return -0.3
            return 3.2 if token != ' by' else 3.5
        if date:
            if token == '\n' and text.rsplit('\n', 1)[-1].startswith('Joined:'):
                return 1.8
            return {' ': 0.89, ',': 0.34, '\n': 0.61, '\n\n': -0.18}.get(token, 0.0)
    if token == ' ' and re.search(r'\b' + _M, text[-60:], re.I):
        continuation = re.search(r"(\d{4}|'\d{2})(,| at| @)$", text)
        if continuation:
            if continuation[1].startswith("'"):
                return 1.03
            return 1.87 if continuation[2] == ',' else 1.47

    md = _MONTH_DAY.search(text)
    if md:
        before = text[:md.start()].rsplit('\n', 1)[-1].strip(' #*')
        before = re.split(r'[.!?] ', before)[-1]
        weekday_prefix = re.sub(r'^(?:Posted:?|Published:?|On)\s+', '', before)
        stamp = (not before or _DAY.fullmatch(weekday_prefix)
                 or _STAMP_LABEL.fullmatch(before))
        if token == ' ' and md[2]:
            if not stamp:
                return 0.35
            if md[1]:
                return 1.95 if before else 3.0
            return 1.79
        if token == ',':
            return (1.43 if md[1] else 0.81) if stamp else 0.0
    weekday = _DAY.search(text.rstrip(' ,'))
    if weekday:
        alone = not text[:weekday.start()].rsplit('\n', 1)[-1].strip(' #*')
        return (1.47 if alone else -0.06) if token == ',' else 0.0
    return -0.05 if token == ';' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, position = '', 0
    else:
        _, text, position = carry
    token = prefix.token_strings[-1]
    value = activation(text, token, position)
    return (doc, (text + token)[-250:], position + 1), float(value)

programs.haiku:
"""Date-stamp separators, forum metadata fields and a few fixed offsets.

The component fires on the punctuation or space that comes right after a date
(or a year) in metadata-like text, where the next thing is usually a time, a
year or a volume number.
"""
import re

READS = ()

MONTH = r"(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?"
DAY = r" \d{1,2}(st|nd|rd|th)?"
YEAR = r"(19|20)\d\d"

# how strongly each separator fires right after a date that ends in a year
AFTER_YEAR = {";": 2.0, " at": 2.5, " by": 1.0, "\n": 0.5, ",": 0.3, " ": 0.4}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if prefix.position == 0:
        # the first token of a row has no context: a fixed value per token
        return carry, (-5.5 if token == "<|endoftext|>" else 0.0)
    text = ""
    for s, d in zip(reversed(prefix.token_strings[:-1]), reversed(prefix.document_ids[:-1])):
        if d != doc or len(text) > 40:
            break
        text = s + text
    if token == ":" and re.search(r"(Joined|Posts)$", text):
        return carry, 3.5  # forum profile field, e.g. "Joined: 02 Sep 2009"
    if token == ":" and text.endswith("Title"):
        return carry, -2.0
    if token == "：" and text.endswith("位置"):
        return carry, 5.0  # "your current location:" breadcrumb
    if token == " Posted" and text.endswith("Originally"):
        return carry, -2.5  # forum quote header
    if re.search(YEAR + "$", text):
        return carry, AFTER_YEAR.get(token, 0.0)
    if re.search(YEAR + ",$", text) and token == " ":
        return carry, 1.0  # "2013, 10:46" style timestamps
    if re.search(MONTH + DAY + r",$", text):
        if token == " ":
            # a date standing alone on a line (a post stamp) is strongest
            line_start = re.search(r"(^|\n)" + MONTH + DAY + ",$", text) is not None
            return carry, 1.8 if line_start else 0.4
        if token == ";":
            return carry, 3.0
    return carry, 0.0

programs.sol:
"""A partial spelling- and boundary-sensitive approximation.

Continuations after short y/Y-ending fragments get signed strengths by
first letter. Selected Chinese first-person, collective and local-region
phrases get negative values. Document starts, declaration keywords, Perl
my-$ declarations and en-dash separators have separate rules.
Only the current and previous token are used; other positions get zero.
"""
import re

READS = ()

# First letters of continuations, not whole-token identities.
Y_ONSET = {
    'a': .1, 'b': .6, 'c': .2, 'd': .8, 'e': .15,
    'f': 1.5, 'g': .3, 'h': .2, 'i': .1, 'j': .35,
    'k': .35, 'l': -.1, 'm': -.15, 'o': .05,
    'p': .05, 'q': -.25, 'r': .1, 's': .15, 't': .2,
    'v': 1.1, 'w': .35, 'x': .35, 'z': -.15,
    'A': .35, 'D': .5, 'F': .3, 'G': .55,
    'M': -.65, 'S': -.35, 'T': .4, 'V': .4,
}
UPPER_Y_ONSET = {
    'B': 2.7, 'F': 2.3, 'D': .9, 'J': .7, 'V': 1.2,
    'M': -.8, 'S': -1.1, 'P': -.9, 'd': 1.4, 'v': 1.1,
    'a': .05, 'e': .27, 'i': .1, 'u': .1, 'T': .7,
    's': -.8, 'L': -.1, 'C': .1,
}
# Administrative regions and institutions, simplified and traditional.
REGIONS = frozenset('省市县縣区區州')
INSTITUTIONS = frozenset('厅廳行军軍党黨校店台臺站')
PREPOSITIONS = frozenset('of to in for on at by with from as into about'.split())
PRONOUNS = frozenset('i you he she it we they me him her us them'.split())


def beginning_value(token):
    word = token.strip()
    low = word.lower()
    if word in {'def', 'int', 'void', 'function'}:
        return 1.5
    if word in {'import', 'package'}:
        return -.8
    if low in {'a', 'an', 'the'}:
        return -.35 if not token.startswith(' ') else -.15
    if low in PREPOSITIONS:
        return -.14
    if low in PRONOUNS:
        return 0.
    if not word:
        return .18
    if word.isalpha():
        if token.startswith(' '):
            return .1
        if len(word) == 1:
            return .2 if word.isupper() else .12
        return -.1 if word[0].isupper() else .04
    if word.isdigit():
        return .02
    if word.startswith(('//', '/*', '#')):
        return -.6
    if word in {'-', '.', '(', '{', '"', '“', '%', ';'}:
        return .45
    return 0.


def predict(token, previous, beginning):
    if beginning:
        return beginning_value(token)
    value = 0.
    if previous.endswith(('y', 'Y')) and token:
        fragment = re.search(r'[A-Za-z]+$', previous)
        size = len(fragment[0]) if fragment else 0
        scale = 1. if size <= 2 else .3 if size <= 4 else 0.
        table = UPPER_Y_ONSET if previous.endswith('Y') else Y_ONSET
        value = scale * table.get(token[0], 0.)
        if previous.endswith('Y') and token.isupper() and len(token) >= 3:
            value *= .2
    # Perl's lexical variable declaration: my $name.
    if previous.strip() == 'my' and token.lstrip().startswith(('$', '\\$')):
        value = 1.7

    # Split phrases: "our province", "the whole army", "this station".
    head = previous[-1:]
    if head in {'全', '本'} and previous != head:
        head = ''
    noun = token if len(token) == 1 else ''
    if head in {'我', '全', '本', '吾'}:
        if noun in REGIONS | INSTITUTIONS or noun in {'辈', '輩', '等', '方'}:
            value = -3.5 if head == '我' else -2.2 if head == '全' else -.8
        elif head == '我' and noun in {'国', '國'}:
            value = -1.8
    # The same local/region-wide phrases can fit inside a single token.
    if len(token) > 1:
        if token[0] in {'我', '全'} and token[1] in REGIONS:
            value = -2.
        elif token.startswith('本站'):
            value = -1.2
        elif token[0] == '我' and token[1] in '会會要在没沒家':
            value = -.8
    if token.startswith('\xa0') and previous.strip() == '–':
        value = -1.25
    if token.strip() == '–' and previous.endswith(('.', '?')):
        value = -.35
    return value


def step(carry, prefix, upstream):
    beginning = (prefix.position == 0 or
                 prefix.document_ids[-1] != prefix.document_ids[-2])
    previous = '' if beginning else prefix.token_strings[-2]
    return None, float(predict(prefix.token_strings[-1], previous, beginning))

"""A negative document-start pulse, not a response to the document's topic.

The pulse persists while the prefix repeats its very first token. Once a
new token appears, predict zero. Its strength is calibrated coarsely from
token shape: words, punctuation, digits, whitespace, and special markers.
Word length and very high English frequency explain some lexical variation;
this deliberately does not memorize individual words' activation values.
"""
from math import log1p
from wordfreq import zipf_frequency

READS = ()


def initial_pulse(text):
    s = text.strip()
    n = len(s)
    if not s:
        value = -2.9 - 1.6 * log1p(len(text))
    elif s.startswith('<|') and s.endswith('|>'):
        value = -9.8
    elif s.isdigit():
        # Larger ASCII digits have a somewhat stronger initial response.
        digit = min(int(s), 6) if s.isascii() else 0
        value = -2.7 - 0.6 * digit
    elif not any(ch.isalpha() for ch in s):
        value = -0.8 - 5.8 * log1p(n)
        if s == ':':
            value += 3.0
    else:
        value = -7.2 - 4.6 * log1p(n) + 0.8 * min(n, 20)
        value += 1.4 * max(0.0, zipf_frequency(s, 'en') - 5.0)
        if not s.isascii():
            value += 0.9
    if '\t' in text:
        value -= 4.1
    if s and text.endswith('\n'):
        value += 0.3
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        value = initial_pulse(prefix.token_strings[-1])
        carry = (doc, token, True, value)
    else:
        _, first, repeating, value = carry
        carry = (doc, first, repeating and token == first, value)
    return carry, carry[3] if carry[2] else 0.0

