import wordnet

READS = ()
PREPOSITIONS = set('''in on at of to for with from by about after before
    under over into onto through without within beyond against during
    behind above following
    than like as between across around along below upon until'''.split())
# Common object-taking verbs that are also often listed as nouns.
OBJECT_ACTIONS = set('''do use make get take put fix change try keep run
    play figure pop give'''.split())
COMPUTATION = set('''compute calculate evaluate simplify expand substitute
    subtract integrate differentiate multiply divide apply'''.split())
# Verbs that commonly introduce a proposition rather than point to an object.
CLAUSE_VERBS = set('''say tell state report note observe notice show suggest indicate
    imply mean ensure require assume suppose know realize conclude agree argue
    prove demonstrate claim expect seem appear explain hope recall consider
    read learn mention reveal announce determine establish assert emphasize
    recognize perceive understand believe remember think feel find confirm
    see notify opine intend propose imagine rule describe provide'''.split())
VERB_HELPERS = set('''to I you we they he she it can could will would should
    may might must shall not dont didnt cannot'''.lower().split())
INTERJECTIONS = set('well yes no yeah yep oh ah hmm wow wait okay ok'.split())
DISCOURSE = set('''however therefore thus instead alternatively otherwise
    indeed actually generally basically now unfortunately'''.split())
CHECKING = {'check', 'verify', 'test', 'confirm'}
THINKING = {'think', 'believe', 'feel', 'understand', 'remember', 'find'}


