    if last == 'but':
        return 2.3 + 0.5 * initial
    if last in {'if', 'when', 'unless', 'whether'}:
        return 3.2
    if last in {'because', 'since', 'though', 'although', 'then', 'once'}:
        return 2.3
    if last in {'and', 'or'}:
        return 1.1 + 1.1 * initial
    if last in {'even', 'that', 'all', 'hence', 'also'}:
        return 1.8
    if last == 'so':
        return 1.8 if initial else 0.6
    if last in {'what', 'how', 'why', 'where'}:
        return 3.3
    if last in {'maybe', 'perhaps', 'wait', 'while', 'however'}:
        return 2.0
    if last in {'now', 'thus', 'therefore', 'have', 'had', 'has'}:
        return 1.4
    if last in {'is', 'was', 'are', 'were', 'can', 'could', 'will',
