GAIN = 0.8  # Conservative amplitude, informed by training intervention scores.
TYPE_HEADER = re.compile(r'\b(class|struct|interface|enum)\b[^;{}]*$')
PATH_OPEN = re.compile(r'''[\s\"'(:#=\[!`{\\]*~?/''')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail = ''
    else:
        tail = carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    line = tail.rsplit('\n', 1)[-1]
    at_start = not line.strip() or bool(re.fullmatch(r'\s*\d+\s+', line))
    value = 0.0

    if token == '://':
        value = 1.55
    elif token == '//' and re.search(r'https?\s*:\s*$', tail):
        value = 1.8
    elif token in {':/', '=/', '#/'}:
        value = 1.1
    elif token != '/' and PATH_OPEN.fullmatch(token):
        if token == ' /':
            value = 0.35
            if tail.rstrip().endswith(':'):
                value = 0.8
        else:
            value = 0.9 if '"' in token or "'" in token else 0.7
    elif word in {'public', 'private', 'protected'}:
        if at_start or '\t' in token:
            value = {'public': 1.15, 'private': 0.72, 'protected': 1.0}[word]
            if '@Override' in tail[-90:]:
                value += 0.3
        else:
            value = 0.03
    elif word == 'import':
        value = -1.95 if tail.rstrip().endswith(';') else -0.05
        if not tail:
            value = -0.58
        elif re.search(r'\bpackage [^\n;]*\n+\s*$', tail):
            value = -0.8
    elif word == 'use' and at_start:
        # Backslash-qualified namespaces distinguish PHP from Rust imports.
        value = -1.5 if tail.rstrip().endswith(';') and '\\' in tail else -0.4
    elif word == 'using' and at_start:
        value = -0.65 if not tail or tail.rstrip().endswith(';') else 0.03
    elif word in {'def', 'fn', 'func', 'pub'}:
        if at_start or (word == 'fn' and re.search(r'\b(pub|async)\s*$', tail)):
            value = {'def': 0.35, 'fn': 0.55, 'func': 0.7, 'pub': 0.5}[word]
    elif word in {'@Override', 'Override'}:
        value = 0.52
    elif word == 'static' and re.search(r'\b(public|private|protected)\s*$', tail):
        value = 0.55
    elif word == 'void':
        value = 0.17
    elif word in {':', '):'} and re.search(r'\bclass[^\n:{}]*$', tail):
        value = 0.8
    elif word == '{' and TYPE_HEADER.search(tail[-220:]):
        value = 0.75
    elif token == '(object' and re.search(r'\bclass\s+\w+\s*$', tail):
        value = 0.9
    elif token == '5' and tail and tail[-1].isascii() and tail[-1].isalpha():
        value = 0.65

    # Decode whitespace escapes after joining, since backslash and n may split.
    text = re.sub(r'\\+([nrt])',
                  lambda m: {'n': '\n', 'r': '\n', 't': '\t'}[m[1]],
                  tail + token).replace('\r', '\n')
    return (doc, text[-300:]), GAIN * value

"""A short h/sibilant-fragment detector.

A preceding h-like consonant fragment gates positive i--t / i--st
and negative u--s / u--l continuations. Transliteration shares these
rules with Cyrillic. A handful of single-token versions also respond.
This approximates a spelling pattern, not the meanings of these words.
Document boundaries reset the one-token memory. Other activations are
left at zero: this is only a partial explanation of the component.
"""
from anyascii import anyascii

READS = ()


def consonant_strength(token):
    raw = token.lower().strip()
    if raw.endswith('ч'):
        return 1.25 if len(raw) == 1 else 0.8
    if raw.endswith(('ш', 'щ', 'х', 'ж')):
        return {'ш': 0.8, 'щ': 0.5, 'х': 0.5, 'ж': 0.13}[raw[-1]]
    s = anyascii(raw)
    for ending, strength in (('wh', 2.4), ('ch', 1.2), ('sh', 0.7),
                             ('ih', 1.1), ('h', 0.4)):
        if s.endswith(ending):
            return strength
    return 0.0


def continuation(token):
    if not token or token[0].isspace():
        return 0.0
    s = anyascii(token).lower()
    if s == 'it':
        return 3.0
    if s == 'ist':
        return 3.85
    if s == 'icht':
        return 3.05
    if s in ('akh', 'ekh'):
        return 3.0
    if s == 't' and token.lower() == 'т':
        return 2.3
    if s in ('us', 'ul', 'uis') and not token.startswith('ü'):
        return -2.85
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = consonant_strength(previous) * continuation(token)
    s = token.lower().strip()
    if s.endswith('whit'):
        value += 4.7
    elif s == 'shit' or token == 'hit':
        value += 1.8
    elif s == 'чит':
        value += 0.8
    elif s == 'hus':
        value -= 2.15
    elif token.strip() == 'thus' and token[0].isspace():
        value -= 0.45
    return (doc, token), float(value)

"""Recognize clause-introducing 'that' and several code separators.

A 'that' following a speech/thought verb, a clause-taking adjective, or a
statement noun is positive; demonstrative and relative uses are usually not.
Python's from-import separator and shell option dashes are also positive.
Comment openers are positive, except URL punctuation. A few non-English
conjunctions and user-header newlines receive fixed values. Other positions are predicted near zero, with a negative alphabetic-token baseline
at a row/document start. The short text tail is reset per document.
"""
import re
from functools import lru_cache
import wordnet

READS = ()
PREPOSITIONS = set('''
in at of on for from with by to into about like than but except after before
'''.split())
OBJECTS = set('''
me you him her us them myself yourself himself herself ourselves themselves
'''.split())
COPULAS = set('is am are was were be been being'.split())
# Lemmas, not a table of token spellings: WordNet supplies inflections.
REPORTING = set("""
tell report claim argue explain admit assert add conclude agree disclose testify opine
maintain write warn teach allege remark contend insist emphasize reiterate
""".split())
EVIDENTIAL = set("""
show prove find discover demonstrate determine establish reveal observe
confirm indicate suggest estimate imply hold
""".split())
COMMON_REPORTS = set('say state announce mention note'.split())
THOUGHT = set("""
think believe know understand realize feel suspect assume suppose decide
recognize notice see hear learn hope remember
""".split())
CLAUSE_ADJECTIVES = set("""
clear evident likely possible certain aware obvious sure confident apparent
true probable
""".split())
ASSERTION_NOUNS = set("""
evidence belief opinion testimony consensus conclusion proposition allegation
""".split())

CLI_COMMANDS = set("""
cat head tail grep egrep rg find sed awk wc ls sort curl wget python python3
pytest git npm node go cargo mvn java javac ffmpeg docker diff test set bash
pip pip3 ssh-keygen ssh-keyscan ssh-copy-id
""".split())

@lru_cache(maxsize=4096)
def bases(word):
    return set(wordnet.base_forms(word, 'verb')) | {word}


def that_value(before):
    words = re.findall(r"[a-z]+", before.lower())
    if not words:
        return 0.05
    word = words[-1]
    if before.rstrip().endswith(('.', '!', '?')):
        return -0.07
    if word in PREPOSITIONS:
        return -0.14
    if word in COPULAS:
        return 0.27
    if word in OBJECTS:
        return 0.45
    if word == 'and':
        return 0.14
    if word in {'so', 'such'}:
        return 0.0
    root = bases(word)
    if root & REPORTING:
        return 0.73
    if root & EVIDENTIAL:
        return 0.53
    if root & COMMON_REPORTS:
        return 0.34 if word != 'note' else 0.20
    if root & THOUGHT:
        return 0.33
    if word in CLAUSE_ADJECTIVES:
        return 0.55
    if word in ASSERTION_NOUNS:
        return 0.50
    # Reported speech can put the hearer's name between 'told' and 'that'.
    original = re.findall(r'[A-Za-z]+', before)
    if original and original[-1][0].isupper():
        if any(bases(w) & REPORTING for w in words[-16:-1]):
            return 0.85
    if word in {'out', 'again', 'earlier', 'today', 'yesterday'}:
        for earlier in words[-5:-1]:
            if bases(earlier) & (
                REPORTING | EVIDENTIAL | COMMON_REPORTS | {'point', 'turn'}
            ):
                return 0.85
    if any(bases(w) & REPORTING for w in words[-12:-1]):
        return 0.35
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    before = '' if first else carry[1]
    token = prefix.token_strings[-1]
    bare = token.strip()
    value = 0.0
    # Code is often carried inside a JSON string, with escaped line breaks.
    if bare in {'import', '-', '--', '//', '#', '/*'}:
        code = re.sub(r'\\+n', '\n', before)
        code = re.sub(r'\\+t', '\t', code)
        line = code.rsplit('\n', 1)[-1]
    if bare.lower() == 'that':
        value = that_value(before)
    elif bare in {'dass', 'daß', 'что', 'že'}:
        value = {'dass': 0.5, 'daß': 0.5, 'что': 0.59, 'že': 0.87}[bare]
    elif bare in {'que', 'qu', 'che'}:
        value = {'que': 0.1, 'qu': 0.03, 'che': 0.23}[bare]
    elif bare == 'import' and re.search(r'\bfrom[ \t]+[\w.]+[ \t]*$', line):
        value = 1.2
    elif token in {' -', ' --'}:
        words = re.findall(r'[A-Za-z0-9_-]+', line)
        command = words[-1] if words else ''
        subcommand = command in {'run', 'install', 'uninstall', 'build', 'exec'}
        shell = (command in CLI_COMMANDS or line.endswith(('.py', '.sh')) or
                 (subcommand and len(words) > 1 and words[-2] in CLI_COMMANDS))
        value = 1.1 if shell else (0.5 if bare == '--' else 0.0)
    elif bare in {'//', '#', '/*', '--'}:
        if bare == '//':
            value = 0.75 if not line.endswith((':', 'http', 'https')) else 0.0
        elif bare == '#':
            numbered_indent = re.fullmatch(r'\s*(?:\d+[:\t]\s*)?', line)
            inline_code = any(c in line for c in '=():;`')
            anchor = line.endswith('](') or re.search(r'https?://\S*$', line)
            if anchor:
                value = -0.1
            else:
                value = 0.7 if numbered_indent or inline_code else 0.15
        elif bare == '/*':
            value = 0.36
        else:
            value = 0.6 if token.startswith(' ') or not line.strip() else 0.0
    elif token == '\n' and re.search(r'<\|im_start\|>user$', before):
        value = 0.18
    if first and value == 0.0 and bare.isalpha():
        value = -0.16 if token.startswith(' ') else -0.44
    return (doc, (before + token)[-180:]), float(value)

"""Approximate a MAN/MN spelling signal, not the meaning 'person'.

Romanization shares the rule across alphabets. Split m|an and m|n
usually produce the largest values; short within-token fragments are
weaker, and familiar long words weaker still. Doubled final n and short
n-before-c/k fragments strengthen it. Katakana spellings are treated
as phonetic, while hiragana n-vowel syllables are not joined to ma.
Short MART is an inhibitory spelling contrast. UTF-8 decoding carries
incomplete characters forward, and all state resets at document changes.
"""
import codecs
from functools import lru_cache
import regex
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
PHONETIC = regex.compile(
    r'[\p{Script=Cyrillic}\p{Script=Arabic}\p{Script=Katakana}]')
KATAKANA = regex.compile(r'\p{Script=Katakana}')
HIRAGANA = regex.compile(r'\p{Script=Hiragana}')


@lru_cache(maxsize=32768)
def spelling(text):
    return (anyascii(text).lower(), bool(PHONETIC.search(text)),
            bool(KATAKANA.search(text)), bool(HIRAGANA.search(text)))


@lru_cache(maxsize=4096)
def frequency(text):
    return zipf_frequency(text, "en")


def response(s, previous, boundary, phonetic, kana_pair, hiragana):
    word = s.strip()
    if word == "man" and phonetic:
        return 3.8
    joined = previous[-4:] + s if not boundary else s
    cross_man = ("man" in joined and "man" not in s
                 and "man" not in previous[-4:])
    if hiragana and s != "n" and previous.endswith("ma"):
        cross_man = False
    if cross_man:
        tail = joined.rsplit("man", 1)[1]
        if kana_pair and len(word) <= 3:
            return 6.3
        if tail == "n":
            return 7.0
        if len(word) <= 4 and (tail in ("c", "k") or tail.startswith("ch")):
            return 7.5
        if tail[:1] and tail[0] in "bcdgkpt":
            return 2.5
        f = frequency(word)
        if f > 4:
            return 5.86
        if not previous.endswith("m"):
            return 0.40
        return 3.29 if f <= 3 else 4.91
    if not boundary and previous.endswith("m") and s.startswith("n"):
        if s == "n":
            return 4.37 if previous.endswith("am") else 1.73
        return 0.36
    if s.endswith("man"):
        if len(word) <= 4:
            return 2.61 if frequency(word) <= 3 else 0.99
        if frequency(word) <= 4.5 and len(word) <= 6:
            return 0.45 if len(word) == 5 else 1.3
        return 0.15
    if "mann" in s:
        return 2.65 if frequency(word) <= 4 else -0.07
    if word.startswith("man"):
        return 0.22
    if word == "mart":
        return -2.0
    return -0.10 if s.startswith("an") else 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_kana = "", False
        decoder = codecs.getincrementaldecoder("utf-8")("replace")
    else:
        _, previous, previous_kana, decoder = carry
    text = decoder.decode(prefix.token_bytes[-1])
    s, phonetic, kana, hiragana = spelling(text)
    boundary = text[:1].isspace() or not previous[-1:].isalpha()
    value = response(s, previous, boundary, phonetic,
                     kana and previous_kana, hiragana)
    if text:
        previous, previous_kana = s, kana
    return (doc, previous, previous_kana, decoder), value

"""Code member boundaries, inferred from indentation and declaration syntax.

Infer a member column from class headers or confirmed function declarations.
Emphasize a return to that column: its initial whitespace, a closing brace,
or the next declaration. A blank line strengthens this boundary signal.
Class headers assume a four-space indentation step. Smaller fallback
responses cover other indentation and declaration tokens; most text is zero.
"""
import re

READS = ()
ACCESS = {'public', 'private', 'protected'}
FUNCTIONS = {'def', 'function', 'func', 'fn'}
DECLARATIONS = ACCESS | FUNCTIONS | {
    'static', 'abstract', 'final', 'virtual', 'override', 'async', 'pub',
    'const', 'let', 'var', 'class', 'interface', 'struct', 'enum',
    'export', 'extern',
}


def indentation(text):
    """Leading columns, counting a tab as four spaces."""
    lead = text[:len(text) - len(text.lstrip(' \t'))]
    return len(lead) + 3 * lead.count('\t')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0, -1, None)
    _, line, last, blank, member, pending = carry
    if pending is not None:
        # A split identifier like func_args is not a declaration of a member.
        first = prefix.token_strings[-1][:1]
        if first.isspace() or first == '(':
            member = pending
    pending = None
    token = prefix.token_strings[-1]
    word = token.strip().split()
    word = word[0] if word else ''
    start = not line.strip()
    horizontal = (bool(token) and not token.strip()
                  and '\n' not in token and '\r' not in token)
    # Estimate where code following this indentation will begin. Pure
    # whitespace tokens are treated as leaving one final separator space.
    column = indentation(line) + indentation(token) + int(horizontal)
    declaration = word in DECLARATIONS
    access_prefix = bool(re.fullmatch(
        r'(public|private|protected)(\s+static)?', line.strip()))
    close = token.strip().startswith('}')
    brace_only = close and not token.strip().strip('},;')

    if start and member >= 0 and column == member:
        if member <= 1:
            value = 0.16
        elif horizontal and (blank or last.strip().startswith('}')):
            value = 4.0
        elif member > 8:
            value = 0.14
        elif brace_only:
            value = 3.27
        elif indentation(line) == 0:
            value = 2.8
        else:
            value = (2.8 if blank else 1.7) if declaration else 0.45
    elif start and horizontal:
        if last.strip().startswith('}'):
            value = 1.86 if blank else 0.67
        elif '\n' in last:
            value = 0.40 if column <= 4 else 0.06
        else:
            value = -0.04
    elif declaration:
        if column <= 3:
            value = 0.16
        elif word in ACCESS or access_prefix:
            value = 1.70
        else:
            value = 0.43
    elif close:
        value = (1.5 if 0 < column <= 4 else 0.6) if start else 0.10
    else:
        if access_prefix:
            value = 1.6 if word in {'static', 'final'} else 0.9
        else:
            value = -0.002

    if start and word in ACCESS | FUNCTIONS:
        pending = indentation(line) + indentation(token)
    parts = token.split('\n')
    for part in parts[:-1]:
        line += part
        if re.search(r'\b(class|interface|struct)\s+\w+.*[{:]', line):
            member = indentation(line) + 4
        blank = 0 if line.strip() else blank + 1
        line = ''
    line += parts[-1]
    if close and start and column < member:
        member = -1
    return (doc, line, token, blank, member, pending), value

programs.haiku:
"""Member boundaries in code: fires where the next line will open a new method or member.

The program reads the text as code and keeps a stack of the blocks still open. Each '{'
opens a class-like body (its header names a class, struct, interface, impl, ...), a
function-like body (its header ends in ')' or '=>', or contains 'function'), or another
block. Each token then gets the value of what it marks:

- the closing brace of a method or function body that sits directly in a class (or at top
  level), together with the blank line after it: the next member is about to start;
- the first word of a member declaration at the start of a line (public, private,
  protected, static, def, constructor, @Override, a doc-comment opener, fn, get);
- the indentation token right after a doc comment ends (*/);
- indentation tokens in general, strongest right after a method has closed and inside a
  class body. The 3-space token ("3") is a particularly strong indentation token here.

Inside a method body, in prose, and on most ordinary code it predicts about zero.
The values are the average activation in each situation, least-squares fitted on 4000
training rows.
"""
import re

READS = ()

CLASS_HEADER = re.compile(r"\b(class|struct|interface|impl|trait|enum|namespace|object)\b")
MEMBER_OPENERS = {
    "public", "private", "protected", "static", "def", "constructor",
    "@Override", "/**", "fn", "get",
}
OTHER_OPENERS = {"void", "func", "async", "init", "__", "pub", "function"}

WEIGHTS = {
    "close_fn_blank_indented": 3.2,  # ' }' then a blank line: a method closes inside a class
    "close_fn_blank": 1.5,           # '}' then a blank line
    "close_fn": 1.0,                 # '}' then a newline
    "close_other_blank": 0.8,        # another block closes, then a blank line
    "close_other": 0.15,
    "indent_after_doc": 2.5,         # indentation right after a doc comment ends
    "indent_after_member_class3": 4.3,
    "indent_after_member_class": 2.8,
    "indent_after_member_top3": 2.9,
    "indent_after_member_top": 0.9,
    "indent_class3": 1.9,
    "indent_class": 0.4,
    "indent_top3": 0.6,
    "member_opener": 1.9,
    "other_opener": 0.8,
    "indent_after_blank": 0.3,
}


def _block_kind(header):
    """What a '{' opens, judged from the text since the last ';', '{' or '}'."""
    if CLASS_HEADER.search(header):
        return "class"
    if header.rstrip().endswith((")", "=>")) or "function" in header:
        return "function"
    return "other"


def _situation(stack, after_member, fresh, tok, prev):
    """Name what this token is, given the open blocks, whether a method just closed, whether
    the token starts a line (fresh), and the previous token."""
    top = stack[-1] if stack else "top"
    stripped = tok.strip()
    indent = tok != "" and stripped == ""
    blank = "\n\n" in tok or "\r\n\r\n" in tok
    blank_before = "\n\n" in prev or "\r\n\r\n" in prev
    three = "3" if tok == "   " else ""
    if "}" in tok:
        method_end = top == "function" and (len(stack) == 1 or stack[-2] == "class")
        if method_end and blank:
            return "close_fn_blank_indented" if tok[:1] in (" ", "\t") else "close_fn_blank"
        if method_end:
            return "close_fn"
        return "close_other_blank" if blank else "close_other"
    if indent and prev.endswith("\n") and "*/" in prev:
        return "indent_after_doc"
    if indent and top in ("class", "top"):
        where = "class" if top == "class" else "top"
        if after_member:
            return "indent_after_member_%s%s" % (where, three)
        return "indent_%s%s" % (where, three)
    if stripped in MEMBER_OPENERS and fresh:
        return "member_opener"
    if stripped in OTHER_OPENERS and fresh:
        return "other_opener"
    if indent and blank_before:
        return "indent_after_blank"
    return "none"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "stack": [], "header": "", "after_member": False, "fresh": True}
    stack = carry["stack"]
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    situation = _situation(stack, carry["after_member"], carry["fresh"], tok, prev)
    value = WEIGHTS.get(situation, 0.0)
    # Update the block stack with this token's characters.
    for ch in tok:
        if ch == "{":
            stack.append(_block_kind(carry["header"]))
            carry["header"] = ""
        elif ch == "}":
            if stack:
                popped = stack.pop()
                parent_is_class = not stack or stack[-1] == "class"
                carry["after_member"] = popped == "function" and parent_is_class
            else:
                carry["after_member"] = True
            carry["header"] = ""
        elif ch == ";":
            carry["header"] = ""
        else:
            carry["header"] = (carry["header"] + ch)[-200:]
    if "\n" in tok:
        carry["fresh"] = tok.split("\n")[-1].strip() == ""
    elif tok.strip() != "":
        carry["fresh"] = False
    if tok.strip() != "" and "}" not in tok:
        carry["after_member"] = False
    return carry, value

programs.sol:
"""A document-end and line-layout cue, not a general lexical predictor.

Noninitial end-of-text markers are positive; line-opening pipes are negative.
Short indentation and list markers receive a shared boundary response,
strongest at early line breaks and after sentences. Paragraph breaks weaken the list/pipe response. The
same declining line-boundary strength is reused for the formatting cues.
Small fixed corrections cover code fences, equation-ending blank lines,
middle-dot separators, and first tokens.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, line, breaks, previous, last_break = 0, '', 0, '', ''
    else:
        _, age, line, breaks, previous, last_break = carry
    at_start = bool(previous) and not line.strip()
    n = max(1, breaks)
    log_age = math.log1p(age)
    sentence = last_break.rstrip().endswith(('.', '!', '?'))
    closing = last_break.rstrip().endswith((')', ']', '}', '"', "'"))
    blank = last_break.count('\n') >= 2
    strength = max(0.0, 2.2 - 0.3 * log_age
                   + 0.4 * sentence + 0.3 * closing)
    boundary = strength / n
    value = 0.0

    if s == '<|endoftext|>':
        value = -0.26 if age == 0 else 2.84 - 0.20 * log_age
    elif s == '|' and at_start:
        average = math.log1p(age / (breaks + 1))
        value = 2.33 - 1.64 * average - 7.2 / (breaks + 1)
        value = min(0.0, max(-7.0, value))
        if blank:
            value *= 0.25
    elif s == '-' and at_start:
        value = max(0.0, 0.06 + boundary - 1.5 * blank / n)
    elif s and not s.strip(' ') and at_start:
        width = len(s)
        if width == 1:
            if line:
                value = -0.05 + 0.7 * boundary / n
            else:
                value = 0.06 + 0.35 * boundary
        elif width in (2, 4):
            gain = 0.9 if width == 2 else 0.4
            value = 0.06 + gain * boundary / math.sqrt(n)
        else:
            value = -0.05
    elif s == '.' and line.strip().isdigit() and breaks:
        weakening = (0.6 * (not sentence) + 1.5 * blank) / n
        value = max(0.0, 0.07 + boundary - weakening)
    elif s == '`\n\n' and previous.endswith('``'):
        value = 0.63
    elif s == '\n\n' and (line.rstrip().endswith('$$') or
                           ('=' in line and any(c.isdigit() for c in line))):
        value = 0.4
    elif s == '··':
        value = 0.86
    elif age == 0:
        value = -0.12
        if s.startswith('<|'):
            value = 0.10
        elif s == ' ':
            value = -0.43
        elif s == '  ':
            value = 1.86

    if '\n' in s:
        last_break = s
    line = (line + s).rsplit('\n', 1)[-1][-100:]
    carry = (doc, age + 1, line, breaks + s.count('\n'), s, last_break)
    return carry, float(value)
